function uid(prefix){return `${prefix}-${Math.random().toString(36).slice(2,8)}${Date.now().toString(36).slice(-4)}`}
function dateKey(d=new Date()){const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,"0"),day=String(d.getDate()).padStart(2,"0");return `${y}-${m}-${day}`}
function parseDay(key){return new Date(`${key}T12:00:00`)}
function isoDay(offset=0){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+offset);return dateKey(d)}
function isoMoment(offsetDays=0,hour=10,minute=0){const d=new Date();d.setDate(d.getDate()+offsetDays);d.setHours(hour,minute,0,0);return d.toISOString()}
function addDaysKey(key,offset){const d=parseDay(key);d.setDate(d.getDate()+offset);return dateKey(d)}
function startOfWeekKey(key){const d=parseDay(key),day=(d.getDay()+6)%7;d.setDate(d.getDate()-day);return dateKey(d)}
function monthStartKey(key){const d=parseDay(key);d.setDate(1);return dateKey(d)}
function monthGridStartKey(key){return startOfWeekKey(monthStartKey(key))}
function monthLabel(key){return new Intl.DateTimeFormat("pt-BR",{month:"long",year:"numeric"}).format(parseDay(key))}
function weekLabel(key){const a=startOfWeekKey(key),b=addDaysKey(a,6);return `${fmtDate(a)} – ${fmtDate(b)}`}
function dayLabel(key){const d=parseDay(key);const s=new Intl.DateTimeFormat("pt-BR",{weekday:"long",day:"2-digit",month:"long",year:"numeric"}).format(d);return s.charAt(0).toUpperCase()+s.slice(1)}
function shortWeekday(key){return new Intl.DateTimeFormat("pt-BR",{weekday:"short"}).format(parseDay(key)).replace(".","")}
function h(value=""){return String(value).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}
function money(v){return CURRENCY.format(Number(v||0))}
function fmtDate(v){if(!v)return"—";const d=new Date(v.length===10?`${v}T12:00:00`:v);return DATE_FMT.format(d)}
function fmtDateTime(v){return v?DATE_TIME_FMT.format(new Date(v)):"—"}
function stage(id){return COMMERCIAL_STAGES.find(s=>s.id===id)||COMMERCIAL_STAGES[0]}
function projectStage(id){return PROJECT_STAGES.find(s=>s.id===id)||PROJECT_STAGES[0]}
function stageIndex(id){return COMMERCIAL_STAGES.findIndex(s=>s.id===id)}
function user(id){return data.users.find(x=>x.id===id)}
function team(id){return data.teams.find(x=>x.id===id)}
function service(id){return data.services.find(x=>x.id===id)}
function fitOption(id){return FIT_OPTIONS.find(x=>x.id===id)||FIT_OPTIONS[0]}
function company(id){return data.companies.find(x=>x.id===id)}
function contact(id){return data.contacts.find(x=>x.id===id)}
function contactsForCompany(companyId){return companyId?data.contacts.filter(x=>x.companyId===companyId):[]}
function contactOptionsForCompany(companyId,selectedId="",emptyLabel="Sem contato"){
  const list=contactsForCompany(companyId),validSelected=list.some(x=>x.id===selectedId)?selectedId:"";
  const emptyText=companyId?(list.length?emptyLabel:"Nenhum contato cadastrado"):"Selecione uma empresa primeiro";
  return `<option value="">${h(emptyText)}</option>${list.map(c=>`<option value="${c.id}" ${c.id===validSelected?"selected":""}>${h(c.name)}${c.role?` · ${h(c.role)}`:""}</option>`).join("")}`;
}
function syncContactSelect(companySelect,contactSelect,preferredContactId=""){
  if(!companySelect||!contactSelect)return;
  const companyId=companySelect.value||"",current=preferredContactId||contactSelect.value||"",list=contactsForCompany(companyId);
  const selected=list.some(c=>c.id===current)?current:"";
  contactSelect.innerHTML=contactOptionsForCompany(companyId,selected,contactSelect.dataset.emptyLabel||"Sem contato");
  contactSelect.disabled=!companyId||list.length===0;
  contactSelect.value=selected;
}
function syncActivityContext(form,kind,id){
  if(!form||!id)return;
  const d=kind==="deal"?deal(id):null,p=kind==="project"?project(id):null;
  const companyId=d?.companyId||p?.companyId||"";
  const linkedDeal=d||(p?.dealId?deal(p.dealId):null);
  const contactId=linkedDeal?.primaryContactId||"";
  const companySelect=form.querySelector('[name="companyId"]'),contactSelect=form.querySelector('[name="contactId"]');
  if(companySelect&&companyId)companySelect.value=companyId;
  syncContactSelect(companySelect,contactSelect,contactId);
}
function deal(id){return data.deals.find(x=>x.id===id)}
function project(id){return data.projects.find(x=>x.id===id)}
function activity(id){return data.activities.find(x=>x.id===id)}
function initials(name=""){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join("").toUpperCase()||"?"}
function avatarColor(id=""){const colors=["#354CE8","#3C574E","#F76103","#39B5CC","#8B5CF6","#C2410C"];let n=0;for(const c of id)n+=c.charCodeAt(0);return colors[n%colors.length]}
function currentUser(){return data.users[0]}
function isClosed(d){return d.stage==="won"||d.stage==="lost"}
function openDeals(){return data.deals.filter(d=>!isClosed(d))}
function weightedValue(d){return Number(d.amount||0)*Number(d.probability??stage(d.stage).probability)/100}
function todayStr(){return dateKey(new Date())}
function daysBetween(a,b){return Math.floor((parseDay(b)-parseDay(a))/86400000)}
function activityStatus(a){if(a.completed)return"done";const t=todayStr();if(a.dueDate<t)return"overdue";if(a.dueDate===t)return"today";return"upcoming"}
function activityType(id){return ACTIVITY_TYPES.find(x=>x.id===id)||ACTIVITY_TYPES.find(x=>x.id==="task")}
function activitySortKey(a){return `${a.dueDate||"9999-12-31"}T${a.dueTime||"23:59"}`}
function latestActivityForDeal(id){return data.activities.filter(a=>a.dealId===id&&!a.completed).sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b)))[0]}
function latestActivityForProject(id){return data.activities.filter(a=>a.projectId===id&&!a.completed).sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b)))[0]}
function activityScopeItems(){const mine=currentUser();if(ui.activityScope==="all")return[...data.activities];if(ui.activityScope==="team"){const ids=team(mine.teamId)?.memberIds||[mine.id];return data.activities.filter(a=>ids.includes(a.ownerId))}return data.activities.filter(a=>a.ownerId===mine.id)}
function activityContext(a){const d=deal(a.dealId),p=project(a.projectId);return{d,p,c:company(a.companyId||d?.companyId||p?.companyId),ct:contact(a.contactId||d?.primaryContactId),u:user(a.ownerId),type:activityType(a.type)}}
function nextCode(kind){const map={company:"EMP",contact:"CON",deal:"OPP",project:"PRJ",proposal:"PROP",contract:"CTR",change:"CR"};const n=data.nextNumbers[kind]++;const year=new Date().getFullYear();return ["project","proposal","contract"].includes(kind)?`${map[kind]}-${year}-${String(n).padStart(4,"0")}`:`${map[kind]}-${String(n).padStart(4,"0")}`}
function defaultDocuments(){return Object.fromEntries(DOCUMENT_DEFS.map(d=>[d.id,{status:"pending",code:"",date:"",fileRef:"",notes:""}]))}
function icpScore(c){let score=0;if(c.clientCount>0&&c.clientCount<=50)score+=35;else if(c.clientCount<=80)score+=20;if(c.teamSize>0&&c.teamSize<=4)score+=30;else if(c.teamSize<=8)score+=15;if((c.digitalMaturity||0)<=3&&c.erp)score+=15;if((c.regimes||"").toLowerCase().includes("simples"))score+=10;if((c.otherSystems||"").trim())score+=10;return Math.min(100,score)}
function ageInStage(d){const latest=[...data.history].filter(x=>x.entityType==="deal"&&x.entityId===d.id&&x.type==="stage").sort((a,b)=>b.createdAt.localeCompare(a.createdAt))[0];const start=latest?.createdAt||d.createdAt;return Math.max(0,Math.floor((Date.now()-new Date(start))/86400000))}

