function migrateLegacy(obj){
  obj=obj||{};obj.version="0.3.4";obj.product="ELEVAR.CRM";obj.settings=obj.settings||{organization:"Elevar Tecnologia"};obj.users=obj.users||[];obj.teams=obj.teams||[];obj.services=obj.services||[];obj.companies=Array.isArray(obj.companies)?obj.companies:[];obj.contacts=Array.isArray(obj.contacts)?obj.contacts:[];obj.deals=Array.isArray(obj.deals)?obj.deals:[];obj.projects=Array.isArray(obj.projects)?obj.projects:[];obj.activities=Array.isArray(obj.activities)?obj.activities:[];obj.history=Array.isArray(obj.history)?obj.history:[];obj.notes=Array.isArray(obj.notes)?obj.notes:[];obj.partners=Array.isArray(obj.partners)?obj.partners:[];
  obj.nextNumbers={company:1,contact:1,deal:1,project:1,proposal:1,contract:1,change:1,...(obj.nextNumbers||{})};
  obj.companies=obj.companies.map(c=>({clientCount:0,teamSize:0,erp:"",otherSystems:"",regimes:"",digitalMaturity:2,...c}));
  obj.contacts=obj.contacts.map(c=>({preferredChannel:c.whatsapp?"WhatsApp":"E-mail",commercialOptIn:true,decisionRole:"decision_maker",...c}));
  const legacyToCommercial={qualified:"discovery",contract_sent:"contract",contract_signed:"contract",deposit_pending:"contract",deposit_paid:"won",kickoff:"won",development:"won",homologation:"won",acceptance:"won",final_payment:"won",warranty:"won"};
  const projectStageMap={kickoff:"kickoff",development:"development",homologation:"homologation",acceptance:"acceptance",final_payment:"acceptance",warranty:"warranty",won:"done",deposit_paid:"awaiting_kickoff",contract_signed:"awaiting_kickoff",deposit_pending:"awaiting_kickoff"};
  const migratedProjects=[];
  obj.deals=obj.deals.map(d=>{
    const c=obj.companies.find(x=>x.id===d.companyId);if(c){if(!c.clientCount&&d.clientCount)c.clientCount=d.clientCount;if(!c.teamSize&&d.teamSize)c.teamSize=d.teamSize;if(!c.erp&&d.erp)c.erp=d.erp}
    const oldStage=d.stage||"lead";const commercialStage=legacyToCommercial[oldStage]||oldStage;
    const diagnostic={date:"",participants:"",duration:45,mainPain:d.mainPain||"",currentProcess:d.currentProcess||"",tools:d.erp||"",frequency:"Mensal",monthlyHours:0,impact:"Médio",summary:d.diagnosticSummary||"",recommendation:d.recommendedPath||"",classification:d.fitClassification||"unclassified",partnerReferral:d.partnerReferral||"",nextStep:""};
    const proposal={code:d.proposalCode||"",version:1,value:Number(d.amount||0),sentDate:"",validUntil:"",status:d.proposalCode?"sent":"draft",paymentTerms:"50% na contratação e 50% no aceite"};
    const contract={code:d.contractCode||"",status:d.contractCode?"signed":"not_started",sentDate:"",signedDate:d.contractCode?(d.updatedAt||""):"",signatureRef:""};
    const nd={...d,stage:commercialStage,probability:stage(commercialStage).probability,diagnostic,proposal,contract,entryStatus:["deposit_paid","kickoff","development","homologation","acceptance","final_payment","warranty","won"].includes(oldStage)?"paid":"pending",convertedProjectId:d.convertedProjectId||""};
    if(["deposit_paid","kickoff","development","homologation","acceptance","final_payment","warranty","won"].includes(oldStage)&&!nd.convertedProjectId){
      const pcode=d.projectCode||`PRJ-${new Date().getFullYear()}-${String(obj.nextNumbers.project++).padStart(4,"0")}`;const pid=uid("p");nd.convertedProjectId=pid;nd.closedAt=nd.closedAt||nd.updatedAt||new Date().toISOString();nd.stage="won";nd.probability=100;
      const docs=defaultDocuments();for(const def of DOCUMENT_DEFS){const old=d.documents?.[def.id];if(old===true)docs[def.id].status="approved"}
      migratedProjects.push({id:pid,code:pcode,dealId:d.id,companyId:d.companyId,title:d.title,serviceId:d.serviceId,ownerId:d.ownerId,stage:projectStageMap[oldStage]||"development",status:oldStage==="won"?"closed":"active",startDate:(d.updatedAt||"").slice(0,10)||todayStr(),targetDate:d.expectedCloseDate||isoDay(30),value:Number(d.amount||0),description:d.description||"",objective:d.recommendedPath||"",inScope:"",outOfScope:"",dependencies:"",risks:"",deliverables:[],documents:docs,financial:{installments:[{id:uid("fin"),label:"Entrada 50%",value:Number(d.amount||0)/2,dueDate:"",status:"paid",invoice:"",paidDate:""},{id:uid("fin"),label:"Aceite 50%",value:Number(d.amount||0)/2,dueDate:d.expectedCloseDate||"",status:oldStage==="won"?"paid":"pending",invoice:"",paidDate:""}]},changeRequests:[],createdAt:d.updatedAt||d.createdAt,updatedAt:d.updatedAt||d.createdAt,closedAt:oldStage==="won"?(d.closedAt||d.updatedAt):null});
    }
    delete nd.clientCount;delete nd.teamSize;delete nd.erp;delete nd.mainPain;delete nd.currentProcess;delete nd.diagnosticSummary;delete nd.recommendedPath;delete nd.partnerReferral;delete nd.proposalCode;delete nd.contractCode;delete nd.projectCode;delete nd.documents;return nd;
  });
  obj.projects.push(...migratedProjects.filter(p=>!obj.projects.some(x=>x.dealId===p.dealId)));
  obj.projects=obj.projects.map(p=>({description:"",objective:"",inScope:"",outOfScope:"",dependencies:"",risks:"",deliverables:[],documents:defaultDocuments(),financial:{installments:[]},changeRequests:[],status:p.stage==="done"?"closed":"active",...p,documents:{...defaultDocuments(),...(p.documents||{})},financial:{installments:[],...(p.financial||{})},changeRequests:Array.isArray(p.changeRequests)?p.changeRequests:[]}));
  obj.activities=obj.activities.map(a=>{const d=obj.deals.find(x=>x.id===a.dealId),p=obj.projects.find(x=>x.id===a.projectId);const start=a.dueTime||"10:00";let end=a.endTime||"";if(!end&&start){const [hh,mm]=start.split(":").map(Number);const total=(hh*60+mm+60)%(24*60);end=`${String(Math.floor(total/60)).padStart(2,"0")}:${String(total%60).padStart(2,"0")}`};return{description:"",priority:"normal",endTime:end,projectId:a.projectId||"",companyId:a.companyId||d?.companyId||p?.companyId||"",contactId:a.contactId||d?.primaryContactId||"",...a}});
  obj.history=obj.history.map(x=>x.entityType?x:{...x,entityType:"deal",entityId:x.dealId||""});
  obj.notes=obj.notes.map(x=>x.entityType?x:{...x,entityType:"deal",entityId:x.dealId||""});
  return obj;
}
function loadData(){try{const raw=localStorage.getItem(STORAGE_KEY);if(raw)return migrateLegacy(JSON.parse(raw));for(const key of LEGACY_STORAGE_KEYS){const legacy=localStorage.getItem(key);if(!legacy)continue;const migrated=migrateLegacy(JSON.parse(legacy));localStorage.setItem(STORAGE_KEY,JSON.stringify(migrated));return migrated}}catch(e){console.warn("Falha ao carregar CRM",e)}const seeded=seedData();localStorage.setItem(STORAGE_KEY,JSON.stringify(seeded));return seeded}
function saveData(){localStorage.setItem(STORAGE_KEY,JSON.stringify(data))}
function resetData(){data=seedData();saveData();ui.dealDrawerId=null;ui.projectDrawerId=null;ui.modal=null;toast("Base vazia restaurada.");render()}
function addHistory(entityType,entityId,text,type="edited"){data.history.push({id:uid("hist"),entityType,entityId,actorId:currentUser().id,type,text,createdAt:new Date().toISOString()})}
function toast(message,tone="success"){ui.toast={message,tone};renderToast();clearTimeout(toast._t);toast._t=setTimeout(()=>{ui.toast=null;renderToast()},3500)}

function navItems(){return [
  ["Comercial",[["dashboard","dashboard","Visão Geral"],["activities","calendarCheck","Agenda"],["pipeline","kanban","Pipeline"],["deals","handshake","Oportunidades"]]],
  ["Relacionamento",[["companies","building","Empresas"],["contacts","contact","Contatos"],["partners","handshake","Parceiros"]]],
  ["Operação",[["projects","briefcase","Projetos"]]],
  ["Gestão",[["team","users","Minha Equipe"],["reports","chart","Relatórios"]]],
  ["Sistema",[["settings","settings","Configurações"]]]
]}
function viewLabel(){const all=navItems().flatMap(x=>x[1]);return all.find(x=>x[0]===ui.view)?.[2]||"CRM"}
function avatar(u,size=""){if(!u)return`<span class="avatar" style="background:#A6ACC5">?</span>`;return`<span class="avatar ${size}" style="background:${avatarColor(u.id)}" title="${h(u.name)}">${h(initials(u.name))}</span>`}
function shell(){const u=currentUser();return `<div class="app"><aside class="sidebar ${ui.sidebarCollapsed?"collapsed":""}"><div class="brand"><span class="brand-symbol">${icon("arrowUpRight",17)}</span><span class="brand-name">ELEVAR<span>.CRM</span></span></div><nav class="nav">${navItems().map(([section,items])=>`<div class="nav-section"><div class="nav-section-title">${section}</div>${items.map(([id,iconName,label])=>`<button class="nav-item ${ui.view===id?"active":""}" data-action="nav" data-view="${id}" title="${label}"><span class="nav-icon">${icon(iconName,17)}</span><span class="nav-label">${label}</span></button>`).join("")}</div>`).join("")}</nav><div class="sidebar-footer"><button class="collapse-btn" data-action="toggle-sidebar">${icon(ui.sidebarCollapsed?"chevronRight":"chevronLeft",16)}<span class="nav-label">Recolher menu</span></button><div class="sidebar-user">${avatar(u)}<div class="sidebar-user-info"><strong>${h(u.name)}</strong><small>${h(u.role)}</small></div></div></div></aside><main class="main"><header class="header"><div class="breadcrumb">${h(viewLabel())}</div><div class="header-search"><span class="search-glyph">${icon("search",16)}</span><input id="global-search" autocomplete="off" placeholder="Pesquisar empresa, contato, oportunidade ou projeto…" value="${h(ui.search)}"><span class="kbd">/</span><div id="search-results"></div></div><div class="header-actions"><button class="btn primary" data-action="new-deal">${icon("plus",15)} Nova oportunidade</button></div></header><section class="content">${renderView()}</section></main>${ui.dealDrawerId?renderDealDrawer(ui.dealDrawerId):""}${ui.projectDrawerId?renderProjectDrawer(ui.projectDrawerId):""}${ui.modal?renderModal():""}<div id="toast-wrap" class="toast-wrap"></div></div>`}
function renderView(){switch(ui.view){case"dashboard":return renderDashboard();case"activities":return renderActivities();case"pipeline":return renderPipeline();case"deals":return renderDeals();case"companies":return renderCompanies();case"contacts":return renderContacts();case"partners":return renderPartners();case"projects":return renderProjects();case"team":return renderTeam();case"reports":return renderReports();case"settings":return renderSettings();default:return renderDashboard()}}
function pageHeader(title,desc,actions=""){return `<div class="page-header"><div><h1 class="page-title">${h(title)}</h1><p class="page-desc">${h(desc)}</p></div><div class="page-actions">${actions}</div></div>`}
function statCard(label,value,hint=""){return `<div class="stat"><div class="stat-label">${h(label)}</div><div class="stat-value">${value}</div><div class="stat-hint">${h(hint)}</div></div>`}
function barList(items,formatter=v=>String(v)){const max=Math.max(1,...items.map(i=>i.value));return `<div class="bar-list">${items.length?items.map(i=>`<div class="bar-row"><div class="bar-label" title="${h(i.label)}">${h(i.label)}</div><div class="bar-track"><div class="bar-fill" style="width:${Math.max(2,i.value/max*100)}%;background:${i.color||"var(--c-primary)"}"></div></div><div class="bar-value">${formatter(i.value)}</div></div>`).join(""):`<div class="empty">Sem dados.</div>`}</div>`}

function attentionItems(){const items=[];for(const d of openDeals()){const next=latestActivityForDeal(d.id),age=ageInStage(d);if(!next)items.push({tone:"warning",icon:"calendar",title:`${d.code} sem próxima ação`,meta:`${company(d.companyId)?.name||""} · ${stage(d.stage).label}`,action:"open-deal",id:d.id});if(d.stage==="proposal"&&age>=5)items.push({tone:"warning",icon:"clock",title:`${d.code} proposta sem follow-up há ${age} dias`,meta:d.title,action:"open-deal",id:d.id});if(d.stage==="contract"&&d.contract?.status!=="signed")items.push({tone:"danger",icon:"fileText",title:`${d.code} aguardando contrato`,meta:d.contract?.status==="sent"?"Contrato enviado, assinatura pendente":"Formalização ainda incompleta",action:"open-deal",id:d.id});if(d.stage==="contract"&&d.contract?.status==="signed"&&d.entryStatus!=="paid")items.push({tone:"danger",icon:"wallet",title:`${d.code} aguardando entrada`,meta:"Contrato assinado; pagamento inicial ainda pendente",action:"open-deal",id:d.id})}
  for(const p of data.projects.filter(p=>p.stage!=="done")){const next=latestActivityForProject(p.id),overdue=p.targetDate&&p.targetDate<todayStr();if(overdue)items.push({tone:"danger",icon:"alert",title:`${p.code} com prazo vencido`,meta:`${company(p.companyId)?.name||""} · ${projectStage(p.stage).label}`,action:"open-project",id:p.id});if(!next)items.push({tone:"warning",icon:"calendar",title:`${p.code} sem próxima ação`,meta:p.title,action:"open-project",id:p.id});const overdueInst=(p.financial?.installments||[]).find(x=>x.status!=="paid"&&x.dueDate&&x.dueDate<todayStr());if(overdueInst)items.push({tone:"danger",icon:"dollar",title:`${p.code} tem parcela vencida`,meta:`${overdueInst.label} · ${money(overdueInst.value)}`,action:"open-project",id:p.id})}
  return items.slice(0,10)}
function renderAttention(items){return `<div class="attention-list">${items.length?items.map(x=>`<button class="attention-item ${x.tone}" data-action="${x.action}" data-id="${x.id}"><span class="attention-icon">${icon(x.icon,16)}</span><span><strong>${h(x.title)}</strong><small>${h(x.meta)}</small></span><span>${icon("chevronRight",15)}</span></button>`).join(""):`<div class="empty"><strong>Nada urgente por aqui</strong>As oportunidades e projetos têm próximos passos definidos.</div>`}</div>`}
function renderDashboard(){const open=openDeals(),pipeline=open.reduce((s,d)=>s+Number(d.amount||0),0),weighted=open.reduce((s,d)=>s+weightedValue(d),0),proposals=open.filter(d=>["proposal","negotiation","contract"].includes(d.stage)),todayActs=data.activities.filter(a=>activityStatus(a)==="today"&&!a.completed),activeProjects=data.projects.filter(p=>p.stage!=="done"),contracted=data.deals.filter(d=>d.stage==="won").reduce((s,d)=>s+Number(d.amount||0),0),received=data.projects.flatMap(p=>p.financial?.installments||[]).filter(x=>x.status==="paid").reduce((s,x)=>s+Number(x.value||0),0),attention=attentionItems();const byStage=COMMERCIAL_STAGES.filter(s=>!["won","lost"].includes(s.id)).map(s=>({label:s.label,value:open.filter(d=>d.stage===s.id).reduce((x,d)=>x+Number(d.amount||0),0),color:s.color}));const upcoming=data.activities.filter(a=>!a.completed).sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b))).slice(0,6);return `<div class="page">${pageHeader("Visão Geral","Decisões do comercial e da operação em uma única tela.",`<button class="btn secondary" data-action="new-activity">${icon("plus",14)} Atividade</button>`)}<div class="stats stats-5">${statCard("Pipeline aberto",money(pipeline),`${open.length} oportunidades`)}${statCard("Forecast ponderado",money(weighted),"Probabilidade por etapa")}${statCard("Propostas / contratação",String(proposals.length),"Negócios mais próximos de fechar")}${statCard("Projetos ativos",String(activeProjects.length),"Execução em andamento")}${statCard("Recebido",money(received),`Contratado histórico: ${money(contracted)}`)}</div><div class="grid-main-side"><div class="dash-main"><div class="panel"><div class="panel-head"><div><div class="panel-title">Precisa da sua atenção</div><div class="panel-sub">Oportunidades e projetos que exigem uma próxima decisão</div></div><span class="chip ${attention.length?"attention-chip":""}">${attention.length}</span></div><div class="panel-body flush">${renderAttention(attention)}</div></div><div class="grid-2 dashboard-secondary"><div class="panel pipeline-summary-panel"><div class="panel-head"><div><div class="panel-title">Pipeline por etapa</div><div class="panel-sub">Somente receita potencial — projetos já vendidos ficam fora</div></div></div><div class="panel-body">${barList(byStage,money)}</div></div><div class="panel upcoming-panel"><div class="panel-head"><div><div class="panel-title">Próximas atividades</div><div class="panel-sub">Agenda comercial e operacional</div></div><button class="btn sm secondary" data-action="nav" data-view="activities">Abrir agenda</button></div><div class="panel-body flush">${upcoming.length?upcoming.map(activityRow).join(""):`<div class="empty">Nenhuma atividade agendada.</div>`}</div></div></div></div><aside class="panel"><div class="panel-head"><div><div class="panel-title">Saúde operacional</div><div class="panel-sub">Resumo rápido dos projetos</div></div></div><div class="panel-body"><div class="health-stack">${PROJECT_STAGES.filter(s=>s.id!=="done").map(s=>{const ps=activeProjects.filter(p=>p.stage===s.id);return `<button class="health-row" data-action="nav-project-stage" data-stage="${s.id}"><span class="stage-dot-mini" style="--tone:${s.color}"></span><span>${h(s.label)}</span><strong>${ps.length}</strong></button>`}).join("")}</div></div></aside></div></div>`}

function renderPipeline(){const owner=ui.filters.owner,serviceId=ui.filters.service;let deals=openDeals();if(owner)deals=deals.filter(d=>d.ownerId===owner);if(serviceId)deals=deals.filter(d=>d.serviceId===serviceId);const filters=`<select class="select filter-select" data-filter="owner"><option value="">Responsável: todos</option>${data.users.map(u=>`<option value="${u.id}" ${owner===u.id?"selected":""}>${h(u.name)}</option>`).join("")}</select><select class="select filter-select" data-filter="service"><option value="">Serviço: todos</option>${data.services.map(s=>`<option value="${s.id}" ${serviceId===s.id?"selected":""}>${h(s.name)}</option>`).join("")}</select>`;return `<div class="page board-page">${pageHeader("Pipeline comercial","O funil termina quando o negócio é ganho ou perdido. Execução vive em Projetos.",`<button class="btn primary" data-action="new-deal">${icon("plus",15)} Nova oportunidade</button>`)}<div class="toolbar">${filters}<span class="toolbar-spacer"></span><span class="muted">${deals.length} oportunidades · ${money(deals.reduce((s,d)=>s+Number(d.amount||0),0))}</span></div><div class="kanban-wrap commercial-board">${COMMERCIAL_STAGES.filter(s=>!["won","lost"].includes(s.id)).map(s=>kanbanColumn(s,deals.filter(d=>d.stage===s.id))).join("")}</div></div>`}
function kanbanColumn(s,deals){return `<section class="kanban-col" data-stage-drop="${s.id}"><div class="kanban-head"><span class="kanban-title">${h(s.label)}</span><span class="kanban-count">${deals.length}</span><span class="kanban-sum">${money(deals.reduce((x,d)=>x+Number(d.amount||0),0))}</span></div><div class="kanban-list">${deals.length?deals.sort((a,b)=>Number(b.amount)-Number(a.amount)).map(dealCard).join(""):`<div class="kanban-empty">Nenhuma oportunidade</div>`}</div></section>`}
function dealCard(d){const c=company(d.companyId),u=user(d.ownerId),a=latestActivityForDeal(d.id),as=a?activityStatus(a):"",fit=fitOption(d.diagnostic?.classification);const age=ageInStage(d);return `<article class="deal-card" draggable="true" data-deal-drag="${d.id}" data-action="open-deal" data-id="${d.id}"><div class="deal-meta"><span class="deal-code">${h(d.code)}</span><span class="chip" style="--tone:${stage(d.stage).color}">${d.probability}%</span></div><div class="deal-title">${h(d.title)}</div><div class="deal-company">${h(c?.name||"Empresa não informada")}</div><div class="deal-fit"><span class="chip dot" style="--tone:${fit.tone}">${h(fit.label)}</span><span class="stage-age ${age>=8?"stale":""}">${age}d na etapa</span></div><div class="deal-money">${money(d.amount)}</div><div class="deal-footer"><span class="owner">${avatar(u)}<span>${h(u?.name.split(" ")[0]||"—")}</span></span><span class="due ${as} ${a?"":"no-activity"}">${a?`${icon(activityType(a.type).icon,12)} ${fmtDate(a.dueDate)}${a.dueTime?` · ${h(a.dueTime)}`:""}`:`${icon("calendar",12)} Sem próxima ação`}</span></div></article>`}
function renderDeals(){const q=(ui.filters.dealSearch||"").toLowerCase(),st=ui.filters.stage;let deals=[...data.deals];if(q)deals=deals.filter(d=>`${d.code} ${d.title} ${company(d.companyId)?.name||""}`.toLowerCase().includes(q));if(st)deals=deals.filter(d=>d.stage===st);return `<div class="page">${pageHeader("Oportunidades","Histórico e situação de todos os negócios comerciais.",`<button class="btn primary" data-action="new-deal">${icon("plus",15)} Nova oportunidade</button>`)}<div class="toolbar"><div class="inline-search"><span>${icon("search",15)}</span><input class="input" data-live-filter="dealSearch" placeholder="Pesquisar por código, empresa ou oportunidade…" value="${h(ui.filters.dealSearch||"")}"></div><select class="select filter-select" data-filter="stage"><option value="">Etapa: todas</option>${COMMERCIAL_STAGES.map(s=>`<option value="${s.id}" ${st===s.id?"selected":""}>${h(s.label)}</option>`).join("")}</select><span class="toolbar-spacer"></span><span class="muted">${deals.length} de ${data.deals.length}</span></div><div class="table-wrap"><table><thead><tr><th style="width:100px">Código</th><th style="width:270px">Oportunidade</th><th style="width:210px">Empresa</th><th style="width:150px">Etapa</th><th style="width:110px">Valor</th><th style="width:120px">Fit</th><th style="width:120px">Fechamento</th></tr></thead><tbody>${deals.sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(d=>`<tr data-action="open-deal" data-id="${d.id}"><td class="cell-muted">${h(d.code)}</td><td class="cell-title">${h(d.title)}</td><td>${h(company(d.companyId)?.name||"—")}</td><td><span class="chip dot" style="--tone:${stage(d.stage).color}">${h(stage(d.stage).label)}</span></td><td class="money">${money(d.amount)}</td><td>${h(fitOption(d.diagnostic?.classification).label)}</td><td>${fmtDate(d.expectedCloseDate)}</td></tr>`).join("")}</tbody></table></div></div>`}

function renderProjects(){const q=(ui.filters.projectSearch||"").toLowerCase(),st=ui.filters.projectStage;let projects=[...data.projects];if(q)projects=projects.filter(p=>`${p.code} ${p.title} ${company(p.companyId)?.name||""}`.toLowerCase().includes(q));if(st)projects=projects.filter(p=>p.stage===st);const active=projects.filter(p=>p.stage!=="done");const contracted=projects.reduce((s,p)=>s+Number(p.value||0),0);const receivable=projects.flatMap(p=>p.financial?.installments||[]).filter(x=>x.status!=="paid").reduce((s,x)=>s+Number(x.value||0),0);return `<div class="page board-page">${pageHeader("Projetos","Execução começa depois da venda. Escopo, financeiro, documentos e mudanças ficam aqui.")}<div class="stats project-stats">${statCard("Projetos ativos",String(active.length),"Em execução ou homologação")}${statCard("Valor contratado",money(contracted),"Projetos listados")}${statCard("A receber",money(receivable),"Parcelas pendentes")}${statCard("Atrasados",String(active.filter(p=>p.targetDate&&p.targetDate<todayStr()).length),"Prazo-alvo vencido")}</div><div class="toolbar"><div class="inline-search"><span>${icon("search",15)}</span><input class="input" data-live-filter="projectSearch" placeholder="Pesquisar projeto…" value="${h(ui.filters.projectSearch||"")}"></div><select class="select filter-select" data-filter="projectStage"><option value="">Etapa: todas</option>${PROJECT_STAGES.map(s=>`<option value="${s.id}" ${st===s.id?"selected":""}>${h(s.label)}</option>`).join("")}</select><span class="toolbar-spacer"></span><span class="muted">${projects.length} projetos</span></div><div class="kanban-wrap project-board">${PROJECT_STAGES.map(s=>projectColumn(s,projects.filter(p=>p.stage===s.id))).join("")}</div></div>`}
function projectColumn(s,projects){return `<section class="kanban-col project-col" data-project-stage-drop="${s.id}"><div class="kanban-head"><span class="kanban-title">${h(s.label)}</span><span class="kanban-count">${projects.length}</span></div><div class="kanban-list">${projects.length?projects.map(projectCard).join(""):`<div class="kanban-empty">Nenhum projeto</div>`}</div></section>`}
function projectCard(p){const c=company(p.companyId),a=latestActivityForProject(p.id),progress=p.deliverables?.length?Math.round(p.deliverables.filter(x=>x.done).length/p.deliverables.length*100):0,received=(p.financial?.installments||[]).filter(x=>x.status==="paid").reduce((s,x)=>s+Number(x.value||0),0);return `<article class="deal-card project-card" draggable="true" data-project-drag="${p.id}" data-action="open-project" data-id="${p.id}"><div class="deal-meta"><span class="deal-code">${h(p.code)}</span><span class="chip dot" style="--tone:${projectStage(p.stage).color}">${progress}%</span></div><div class="deal-title">${h(p.title)}</div><div class="deal-company">${h(c?.name||"—")}</div><div class="project-progress"><span style="width:${progress}%"></span></div><div class="project-card-metrics"><span>${money(p.value)}</span><span>Recebido ${money(received)}</span></div><div class="deal-footer"><span class="due ${p.targetDate&&p.targetDate<todayStr()?"overdue":"upcoming"}">${icon("clock",12)} ${fmtDate(p.targetDate)}</span><span class="due ${a?activityStatus(a):"no-activity"}">${a?fmtDate(a.dueDate):"Sem próxima ação"}</span></div></article>`}

function renderActivities(){const anchor=ui.calendarAnchor||todayStr(),view=ui.calendarView||"week",scoped=activityScopeItems(),overdue=scoped.filter(a=>activityStatus(a)==="overdue").length;const controls=`<div class="agenda-controls"><div class="agenda-nav"><button class="icon-button" data-action="calendar-prev" aria-label="Anterior">${icon("chevronLeft",16)}</button><button class="btn sm secondary" data-action="calendar-today">Hoje</button><button class="icon-button" data-action="calendar-next" aria-label="Próximo">${icon("chevronRight",16)}</button><strong class="agenda-period">${h(calendarPeriodLabel(view,anchor))}</strong></div><div class="agenda-right"><select class="select compact" data-agenda-scope><option value="mine" ${ui.activityScope==="mine"?"selected":""}>Minha agenda</option><option value="team" ${ui.activityScope==="team"?"selected":""}>Minha equipe</option><option value="all" ${ui.activityScope==="all"?"selected":""}>Todos</option></select><div class="segmented compact">${[["day","Dia"],["week","Semana"],["month","Mês"],["list","Lista"]].map(([id,label])=>`<button class="${view===id?"active":""}" data-action="calendar-view" data-value="${id}">${label}</button>`).join("")}</div></div></div>`;return `<div class="page agenda-page">${pageHeader("Agenda","Reuniões, follow-ups e próximos passos de vendas e projetos.",`<button class="btn primary" data-action="new-activity" data-date="${anchor}">${icon("plus",15)} Nova atividade</button>`)}${overdue?`<div class="agenda-alert">${icon("clock",15)} <strong>${overdue} atividade${overdue>1?"s":""} atrasada${overdue>1?"s":""}</strong><span>Revise os próximos passos.</span></div>`:""}${controls}<div class="agenda-surface">${view==="month"?renderMonthCalendar(anchor,scoped):view==="day"?renderDayCalendar(anchor,scoped):view==="list"?renderAgendaList(scoped):renderWeekCalendar(anchor,scoped)}</div></div>`}
function calendarPeriodLabel(view,anchor){if(view==="month")return monthLabel(anchor);if(view==="day")return dayLabel(anchor);if(view==="week")return weekLabel(anchor);return"Todas as atividades"}
function renderDayCalendar(anchor,acts){const dayActs=acts.filter(a=>a.dueDate===anchor).sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b))),overdue=acts.filter(a=>activityStatus(a)==="overdue").sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b)));return `<div class="agenda-day-layout"><div class="panel"><div class="panel-head"><div><div class="panel-title">${h(dayLabel(anchor))}</div><div class="panel-sub">${dayActs.length} atividades programadas</div></div><button class="btn sm secondary" data-action="new-activity" data-date="${anchor}">${icon("plus",13)} Adicionar</button></div><div class="day-timeline">${dayActs.length?dayActs.map(a=>calendarAgendaItem(a,true)).join(""):`<div class="empty"><strong>Dia livre</strong>Não há atividades agendadas.</div>`}</div></div><aside class="panel"><div class="panel-head"><div><div class="panel-title">Pendências atrasadas</div><div class="panel-sub">Atividades ainda não concluídas</div></div></div><div class="panel-body flush">${overdue.length?overdue.slice(0,8).map(a=>calendarAgendaItem(a,false)).join(""):`<div class="empty">Nenhuma pendência atrasada.</div>`}</div></aside></div>`}
function renderWeekCalendar(anchor,acts){const start=startOfWeekKey(anchor),days=Array.from({length:7},(_,i)=>addDaysKey(start,i));return `<div class="week-calendar"><div class="week-calendar-head">${days.map(k=>`<button class="week-day-head ${k===todayStr()?"today":""}" data-action="calendar-focus-day" data-date="${k}"><span>${h(shortWeekday(k))}</span><strong>${parseDay(k).getDate()}</strong></button>`).join("")}</div><div class="week-calendar-body">${days.map(k=>{const items=acts.filter(a=>a.dueDate===k).sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b)));return `<div class="week-day-col ${k===todayStr()?"today":""}"><button class="day-add" data-action="new-activity" data-date="${k}">${icon("plus",12)} Adicionar</button>${items.map(calendarEvent).join("")}</div>`}).join("")}</div></div>`}
function renderMonthCalendar(anchor,acts){const start=monthGridStartKey(anchor),month=parseDay(anchor).getMonth(),days=Array.from({length:42},(_,i)=>addDaysKey(start,i));return `<div class="month-calendar"><div class="month-weekdays">${["Seg","Ter","Qua","Qui","Sex","Sáb","Dom"].map(x=>`<div>${x}</div>`).join("")}</div><div class="month-grid">${days.map(k=>{const inMonth=parseDay(k).getMonth()===month,items=acts.filter(a=>a.dueDate===k).sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b)));return `<div class="month-cell ${inMonth?"":"outside"} ${k===todayStr()?"today":""}"><div class="month-cell-head"><button data-action="calendar-focus-day" data-date="${k}">${parseDay(k).getDate()}</button><button class="month-add" data-action="new-activity" data-date="${k}">${icon("plus",12)}</button></div><div class="month-events">${items.slice(0,3).map(a=>calendarEvent(a,true)).join("")}${items.length>3?`<button class="month-more" data-action="calendar-focus-day" data-date="${k}">+${items.length-3} mais</button>`:""}</div></div>`}).join("")}</div></div>`}
function renderAgendaList(acts){const tab=ui.filters.activity||"today";let rows=[...acts];rows=rows.filter(a=>{const st=activityStatus(a);if(tab==="all")return true;if(tab==="done")return st==="done";return st===tab});rows.sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b)));const counts={today:acts.filter(a=>activityStatus(a)==="today").length,overdue:acts.filter(a=>activityStatus(a)==="overdue").length,upcoming:acts.filter(a=>activityStatus(a)==="upcoming").length,done:acts.filter(a=>activityStatus(a)==="done").length,all:acts.length};return `<div class="panel"><div class="panel-head agenda-list-head"><div class="segmented">${[["today","Hoje"],["overdue","Atrasadas"],["upcoming","Próximas"],["done","Concluídas"],["all","Todas"]].map(([id,label])=>`<button class="${tab===id?"active":""}" data-action="activity-tab" data-value="${id}">${label} · ${counts[id]}</button>`).join("")}</div></div><div class="panel-body flush">${rows.length?rows.map(activityRow).join(""):`<div class="empty">Nenhuma atividade neste filtro.</div>`}</div></div>`}
function calendarEvent(a,compact=false){const {c,type}=activityContext(a),st=activityStatus(a);return `<button class="calendar-event ${compact?"compact":""} ${st}" data-action="open-activity" data-id="${a.id}" style="--activity-color:${type.color}"><span class="calendar-event-time">${h(a.dueTime||"—")}</span><span class="calendar-event-body"><strong>${h(a.subject)}</strong>${compact?"":`<small>${h(c?.name||"Atividade interna")}</small>`}</span></button>`}
function activityContextLabel(a){const {d,p,c}=activityContext(a);if(p)return `${c?.name||""} · ${p.code}`;if(d)return `${c?.name||""} · ${d.code}`;return c?.name||"Atividade interna"}
function calendarAgendaItem(a,showDate=false){const {type,u}=activityContext(a),st=activityStatus(a);return `<div class="agenda-item ${st}"><div class="agenda-time"><strong>${h(a.dueTime||"—")}</strong>${a.endTime?`<small>${h(a.endTime)}</small>`:""}</div><button class="agenda-type" data-action="open-activity" data-id="${a.id}" style="--activity-color:${type.color}">${icon(type.icon,16)}</button><button class="agenda-item-main" data-action="open-activity" data-id="${a.id}"><strong>${h(a.subject)}</strong><small>${h(activityContextLabel(a))}${showDate?` · ${fmtDate(a.dueDate)}`:""}</small></button><div class="agenda-owner">${avatar(u)}<span>${h(u?.name.split(" ")[0]||"—")}</span></div>${a.completed?`<span class="chip">Concluída</span>`:`<button class="icon-button success" data-action="complete-activity" data-id="${a.id}">${icon("checkSquare",15)}</button>`}</div>`}
function activityRow(a){const {type,u}=activityContext(a),status=activityStatus(a);return `<div class="activity-row ${status}"><button class="activity-icon" data-action="open-activity" data-id="${a.id}" style="--activity-color:${type.color}">${icon(type.icon,16)}</button><button class="activity-main" data-action="open-activity" data-id="${a.id}"><strong>${h(a.subject)}</strong><small>${h(activityContextLabel(a))}</small></button><span class="activity-date">${fmtDate(a.dueDate)} · ${h(a.dueTime||"")}</span><span class="activity-type">${h(type.label)}</span><span class="compact-owner">${avatar(u)} ${h(u?.name.split(" ")[0]||"—")}</span>${a.completed?`<span class="chip">Concluída</span>`:`<button class="icon-button success" data-action="complete-activity" data-id="${a.id}">${icon("checkSquare",15)}</button>`}</div>`}

function renderCompanies(){return `<div class="page">${pageHeader("Empresas","Perfil do escritório, fit com o ICP, relacionamento e histórico comercial.",`<button class="btn primary" data-action="new-company">${icon("plus",15)} Nova empresa</button>`)}<div class="company-grid">${data.companies.map(c=>{const score=icpScore(c),ds=data.deals.filter(d=>d.companyId===c.id),ps=data.projects.filter(p=>p.companyId===c.id),won=ds.filter(d=>d.stage==="won").reduce((s,d)=>s+Number(d.amount||0),0);return `<article class="company-card" data-action="open-company" data-id="${c.id}"><div class="company-card-top"><div><span class="cell-muted">${h(c.code)}</span><h3>${h(c.name)}</h3><p>${h(c.segment||"—")} · ${h(c.city||"—")}</p></div><span class="icp-score ${score>=75?"great":score>=50?"good":"low"}">${score}/100</span></div><div class="company-facts"><span>${c.clientCount||0} empresas</span><span>${c.teamSize||0} pessoas</span><span>${h(c.erp||"ERP não informado")}</span></div><div class="company-card-foot"><span>${ds.filter(d=>!isClosed(d)).length} oportunidades</span><span>${ps.filter(p=>p.stage!=="done").length} projetos ativos</span><strong>${money(won)} gerados</strong></div></article>`}).join("")}</div></div>`}
function renderContacts(){return `<div class="page">${pageHeader("Contatos","Pessoas, papel na decisão e canal preferido de relacionamento.",`<button class="btn primary" data-action="new-contact">${icon("plus",15)} Novo contato</button>`)}<div class="table-wrap"><table><thead><tr><th style="width:220px">Contato</th><th style="width:220px">Empresa</th><th style="width:170px">Papel</th><th style="width:130px">Canal</th><th style="width:210px">E-mail</th><th>Telefone</th></tr></thead><tbody>${data.contacts.map(ct=>`<tr data-action="open-contact" data-id="${ct.id}"><td class="cell-title">${h(ct.name)}</td><td>${h(company(ct.companyId)?.name||"—")}</td><td>${h(DECISION_ROLES.find(x=>x[0]===ct.decisionRole)?.[1]||"—")}</td><td>${h(ct.preferredChannel||"—")}</td><td>${h(ct.email||"—")}</td><td>${h(ct.phone||"—")}</td></tr>`).join("")}</tbody></table></div></div>`}
function renderPartners(){return `<div class="page">${pageHeader("Parceiros","Rede de especialistas para indicar quando a melhor solução não é a Elevar.",`<button class="btn primary" data-action="new-partner">${icon("plus",15)} Novo parceiro</button>`)}<div class="company-grid partner-grid">${data.partners.map(p=>{const referrals=data.deals.filter(d=>d.diagnostic?.partnerId===p.id).length;return `<article class="company-card partner-card"><div class="company-card-top"><div><span class="cell-muted">${h(p.category||"Parceiro")}</span><h3>${h(p.name)}</h3><p>${h(p.contact||"Contato não informado")}</p></div><span class="icp-score good">${referrals}</span></div><div class="description">${h(p.notes||"Sem observações.")}</div><div class="company-card-foot"><span>${referrals} indicações registradas</span><strong>${h(p.city||"")}</strong></div></article>`}).join("")||`<div class="empty">Nenhum parceiro cadastrado.</div>`}</div></div>`}
function renderTeam(){const u=currentUser(),open=openDeals().filter(d=>d.ownerId===u.id),activeP=data.projects.filter(p=>p.ownerId===u.id&&p.stage!=="done"),overdue=data.activities.filter(a=>a.ownerId===u.id&&activityStatus(a)==="overdue").length;return `<div class="page">${pageHeader("Minha Equipe","Capacidade comercial e operacional do workspace.")}<div class="team-grid"><article class="team-card"><div class="team-card-head">${avatar(u)}<div><strong>${h(u.name)}</strong><small>${h(u.role)}</small></div></div><div class="team-metrics"><div><strong>${open.length}</strong><small>oportunidades</small></div><div><strong>${activeP.length}</strong><small>projetos</small></div><div><strong>${overdue}</strong><small>atrasadas</small></div></div><div><span class="muted">Pipeline aberto</span><div class="deal-money">${money(open.reduce((s,d)=>s+Number(d.amount||0),0))}</div></div></article></div></div>`}
function renderReports(){const closed=data.deals.filter(isClosed),won=closed.filter(d=>d.stage==="won"),lost=closed.filter(d=>d.stage==="lost"),winRate=closed.length?won.length/closed.length*100:0,cycles=won.filter(d=>d.closedAt).map(d=>(new Date(d.closedAt)-new Date(d.createdAt))/86400000),avgCycle=cycles.length?cycles.reduce((a,b)=>a+b,0)/cycles.length:0;const diag=data.deals.filter(d=>d.diagnostic?.classification&&d.diagnostic.classification!=="unclassified"),proposalCount=diag.filter(d=>["proposal","negotiation","contract","won"].includes(d.stage)).length,diagToProposal=diag.length?proposalCount/diag.length*100:0;const bySource=SOURCES.map(s=>({label:s,value:data.deals.filter(d=>d.source===s).length})).filter(x=>x.value).sort((a,b)=>b.value-a.value),byFit=FIT_OPTIONS.filter(x=>x.id!=="unclassified").map(x=>({label:x.label,value:data.deals.filter(d=>d.diagnostic?.classification===x.id).length,color:x.tone})).filter(x=>x.value),byProjectStage=PROJECT_STAGES.map(s=>({label:s.label,value:data.projects.filter(p=>p.stage===s.id).length,color:s.color})).filter(x=>x.value),losses=Object.entries(lost.reduce((m,d)=>{const k=d.lostReason||"Não informado";m[k]=(m[k]||0)+1;return m},{})).map(([label,value])=>({label,value}));return `<div class="page">${pageHeader("Relatórios","Conversão comercial separada da execução dos projetos.")}<div class="stats">${statCard("Win rate",`${winRate.toFixed(1).replace('.',',')}%`,`${won.length} ganhos de ${closed.length} encerrados`)}${statCard("Diagnóstico → proposta",`${diagToProposal.toFixed(1).replace('.',',')}%`,`${diag.length} diagnósticos classificados`)}${statCard("Ticket médio",money(won.length?won.reduce((s,d)=>s+Number(d.amount||0),0)/won.length:0),"Vendas ganhas")}${statCard("Ciclo comercial",`${avgCycle.toFixed(1).replace('.',',')} dias`,"Criação até venda ganha")}</div><div class="grid-2"><div class="panel"><div class="panel-head"><div><div class="panel-title">Origem das oportunidades</div></div></div><div class="panel-body">${barList(bySource)}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Classificação pós-diagnóstico</div></div></div><div class="panel-body">${barList(byFit)}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Projetos por etapa</div></div></div><div class="panel-body">${barList(byProjectStage)}</div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Motivos de perda</div></div></div><div class="panel-body">${barList(losses)}</div></div></div></div>`}
function renderSettings(){return `<div class="page narrow">${pageHeader("Configurações","Workspace, backups e dados locais da versão protótipo.")}<div class="panel"><div class="panel-head"><div><div class="panel-title">Organização</div></div></div><div class="panel-body"><div class="field"><label>Nome do workspace</label><input class="input" id="org-name" value="${h(data.settings.organization)}"></div><div style="margin-top:10px"><button class="btn primary" data-action="save-org">Salvar</button></div></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Dados</div><div class="panel-sub">Ainda armazenados no navegador — backend virá na fase 1.0</div></div></div><div class="panel-body"><p class="muted">${data.companies.length} empresas · ${data.contacts.length} contatos · ${data.deals.length} oportunidades · ${data.projects.length} projetos · ${data.activities.length} atividades.</p><div class="toolbar" style="margin-top:12px"><button class="btn secondary" data-action="export-json">${icon("download",14)} Exportar JSON</button><button class="btn secondary" data-action="import-json">${icon("upload",14)} Importar JSON</button><button class="btn danger" data-action="reset-data">${icon("rotate",14)} Restaurar base vazia</button><input type="file" id="json-import" accept="application/json" hidden></div></div></div><div class="panel"><div class="panel-head"><div><div class="panel-title">Sobre esta versão</div><div class="panel-sub">ELEVAR.CRM 0.3.4</div></div></div><div class="panel-body"><p>Arquitetura separada entre Comercial e Projetos. Venda ganha deixa de permanecer no pipeline e pode ser convertida em projeto com escopo, entregáveis, financeiro, documentos e Change Requests próprios.</p></div></div></div>`}

function renderCommercialStepper(d){const current=stageIndex(d.stage);return `<div class="stage-stepper process-stepper">${COMMERCIAL_STAGES.filter(s=>!["lost"].includes(s.id)).map((s,i)=>`<div class="stage-node ${current>i?"done":current===i?"current":""}"><button class="stage-btn" data-action="set-stage" data-id="${d.id}" data-stage="${s.id}"><span class="stage-dot">${current>i?"✓":i+1}</span><span class="stage-label">${h(s.label)}</span></button></div>`).join("")}</div>`}
function propertySelect(label,field,value,options,kind="deal"){return `<div class="prop-group"><div class="prop-row"><label>${h(label)}</label><select class="select" data-${kind}-field="${field}">${options.map(([v,l])=>`<option value="${h(v)}" ${String(value)===String(v)?"selected":""}>${h(l)}</option>`).join("")}</select></div></div>`}
function propertyInput(label,field,value,type="text",kind="deal"){return `<div class="prop-group"><div class="prop-row"><label>${h(label)}</label><input class="input" type="${type}" data-${kind}-field="${field}" value="${h(value??"")}"></div></div>`}
function textAreaField(label,path,value,kind="deal",placeholder=""){return `<label class="journey-textarea">${h(label)}<textarea class="textarea" data-${kind}-path="${path}" placeholder="${h(placeholder)}">${h(value||"")}</textarea></label>`}
function inputPath(label,path,value,type="text",kind="deal",placeholder=""){return `<label>${h(label)}<input class="input" type="${type}" data-${kind}-path="${path}" value="${h(value??"")}" placeholder="${h(placeholder)}"></label>`}
function selectPath(label,path,value,options,kind="deal"){return `<label>${h(label)}<select class="select" data-${kind}-path="${path}">${options.map(([v,l])=>`<option value="${h(v)}" ${String(value)===String(v)?"selected":""}>${h(l)}</option>`).join("")}</select></label>`}
function renderDealDrawer(id){const d=deal(id);if(!d)return"";const c=company(d.companyId),ct=contact(d.primaryContactId),u=user(d.ownerId),a=latestActivityForDeal(d.id),history=data.history.filter(x=>x.entityType==="deal"&&x.entityId===d.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),notes=data.notes.filter(x=>x.entityType==="deal"&&x.entityId===d.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),acts=data.activities.filter(x=>x.dealId===d.id).sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b))),fit=fitOption(d.diagnostic?.classification);const canConvert=(d.stage==="won"&&!d.convertedProjectId)||(d.stage==="contract"&&d.contract?.status==="signed"&&d.entryStatus==="paid"&&!d.convertedProjectId);return `<div class="drawer-overlay" data-action="close-drawer"><aside class="drawer"><div class="drawer-top"><span class="drawer-code">${h(d.code)}</span><span class="chip dot" style="--tone:${stage(d.stage).color}">${h(stage(d.stage).label)}</span><span class="chip dot" style="--tone:${fit.tone}">${h(fit.label)}</span><span class="toolbar-spacer"></span>${canConvert?`<button class="btn sm primary" data-action="convert-project" data-id="${d.id}">${icon("briefcase",13)} ${d.stage==="won"?"Criar projeto":"Ganhar + criar projeto"}</button>`:""}${d.convertedProjectId?`<button class="btn sm secondary" data-action="open-project" data-id="${d.convertedProjectId}">${icon("arrowUpRight",13)} Abrir projeto</button>`:""}<button class="btn sm secondary" data-action="new-activity" data-deal="${d.id}">${icon("plus",13)} Atividade</button><button class="close" data-action="close-drawer">${icon("x",17)}</button></div><div class="drawer-body"><main class="drawer-main"><div><div class="drawer-title">${h(d.title)}</div><div class="drawer-company">${h(c?.name||"—")} · ${h(ct?.name||"Sem contato principal")}</div></div>${renderCommercialStepper(d)}<section class="section"><div class="section-title">Próxima ação</div>${a?`<button class="note clickable-note" data-action="open-activity" data-id="${a.id}"><div class="note-head"><strong>${icon(activityType(a.type).icon,14)} ${h(a.subject)}</strong><span class="due ${activityStatus(a)}">${fmtDate(a.dueDate)} ${h(a.dueTime)}</span></div></button>`:`<div class="empty"><strong>Nenhuma próxima ação</strong>Esta oportunidade aparecerá no painel “Precisa da sua atenção”.<div style="margin-top:8px"><button class="btn sm secondary" data-action="new-activity" data-deal="${d.id}">${icon("plus",13)} Agendar</button></div></div>`}</section><section class="section"><div class="tabs">${[["summary","Resumo"],["diagnostic","Diagnóstico"],["proposal","Proposta & contrato"],["activities",`Atividades · ${acts.length}`],["history","Histórico"],["notes","Notas"]].map(([v,l])=>`<button class="tab ${ui.drawerTab===v?"active":""}" data-action="drawer-tab" data-value="${v}">${l}</button>`).join("")}</div><div>${renderDealTab(d,acts,history,notes)}</div></section></main><aside class="drawer-side"><div class="mini-stats"><div class="mini-stat"><small>Valor</small><strong>${money(d.amount)}</strong></div><div class="mini-stat"><small>Ponderado</small><strong>${money(weightedValue(d))}</strong></div></div>${propertySelect("Etapa","stage",d.stage,COMMERCIAL_STAGES.map(s=>[s.id,s.label]))}${propertyInput("Valor","amount",d.amount,"number")}${propertySelect("Responsável","ownerId",d.ownerId,data.users.map(x=>[x.id,x.name]))}${propertySelect("Serviço","serviceId",d.serviceId,data.services.map(x=>[x.id,x.name]))}${propertySelect("Empresa","companyId",d.companyId,data.companies.map(x=>[x.id,x.name]))}${propertySelect("Contato","primaryContactId",d.primaryContactId,data.contacts.filter(x=>x.companyId===d.companyId).map(x=>[x.id,x.name]))}${propertySelect("Origem","source",d.source,SOURCES.map(x=>[x,x]))}${propertyInput("Previsão","expectedCloseDate",d.expectedCloseDate,"date")}${d.stage==="lost"?propertyInput("Motivo da perda","lostReason",d.lostReason||"","text"):""}<div class="prop-group"><div class="section-title">Metadados</div><div class="prop-row"><label>ICP da empresa</label><span>${icpScore(c)}/100</span></div><div class="prop-row"><label>Dias na etapa</label><span>${ageInStage(d)}</span></div><div class="prop-row"><label>Criada</label><span>${fmtDateTime(d.createdAt)}</span></div></div></aside></div></aside></div>`}
function renderDealTab(d,acts,history,notes){if(ui.drawerTab==="summary")return `<div class="journey-grid"><div class="journey-panel"><div class="section-title">Contexto inicial</div><div class="description">${h(d.description||"Sem descrição.")}</div></div><div class="journey-panel"><div class="section-title">Empresa / ICP</div><div class="info-grid"><div><small>Carteira</small><strong>${company(d.companyId)?.clientCount||0}</strong></div><div><small>Equipe</small><strong>${company(d.companyId)?.teamSize||0}</strong></div><div><small>ERP</small><strong>${h(company(d.companyId)?.erp||"—")}</strong></div><div><small>ICP score</small><strong>${icpScore(company(d.companyId))}/100</strong></div></div></div></div>`;if(ui.drawerTab==="diagnostic")return renderDiagnostic(d);if(ui.drawerTab==="proposal")return renderProposalContract(d);if(ui.drawerTab==="activities")return `<div class="deal-activity-list">${acts.length?acts.map(a=>calendarAgendaItem(a,true)).join(""):`<div class="empty">Nenhuma atividade vinculada.</div>`}</div>`;if(ui.drawerTab==="history")return `<div class="timeline">${history.map(historyItem).join("")}</div>`;return `<div class="timeline">${notes.map(noteItem).join("")}</div><form id="note-form" class="composer" data-entity="deal" data-id="${d.id}" style="margin-top:12px"><textarea class="textarea" name="note" placeholder="Adicionar nota interna…"></textarea><button class="btn primary" type="submit">Adicionar</button></form>`}
function renderDiagnostic(d){const x=d.diagnostic||{},fit=fitOption(x.classification);return `<div class="journey-grid"><div class="journey-panel"><div class="section-title">Sessão de diagnóstico gratuita</div><div class="journey-fields">${inputPath("Data","diagnostic.date",x.date,"date")}${inputPath("Duração (min)","diagnostic.duration",x.duration,"number")}${inputPath("Participantes","diagnostic.participants",x.participants,"text","deal","Nomes / cargos")}${inputPath("Ferramentas envolvidas","diagnostic.tools",x.tools,"text","deal","ERP, Excel, WhatsApp…")}${inputPath("Frequência","diagnostic.frequency",x.frequency)}${inputPath("Horas/mês estimadas","diagnostic.monthlyHours",x.monthlyHours,"number")}${selectPath("Impacto","diagnostic.impact",x.impact,[["Baixo","Baixo"],["Médio","Médio"],["Alto","Alto"]])}${selectPath("Classificação","diagnostic.classification",x.classification,FIT_OPTIONS.map(f=>[f.id,f.label]))}${inputPath("Próximo passo","diagnostic.nextStep",x.nextStep,"text","deal","Ex.: Fazer proposta")}</div>${textAreaField("Principal dor","diagnostic.mainPain",x.mainPain)}${textAreaField("Processo atual","diagnostic.currentProcess",x.currentProcess)}</div><div class="journey-panel"><div class="section-title">Recomendação Elevar</div><div class="fit-summary" style="--fit:${fit.tone}"><strong>${h(fit.label)}</strong><p>${h(fit.description)}</p></div>${textAreaField("Resumo do diagnóstico","diagnostic.summary",x.summary)}${textAreaField("Caminho recomendado","diagnostic.recommendation",x.recommendation)}${x.classification==="partner_fit"?`${selectPath("Parceiro recomendado","diagnostic.partnerId",x.partnerId||"",[["","Selecione…"],...data.partners.map(p=>[p.id,p.name])])}${textAreaField("Observação da indicação","diagnostic.partnerReferral",x.partnerReferral)}`:""}<div class="diagnostic-actions">${x.classification==="elevar_fit"?`<button class="btn primary" data-action="diagnostic-next" data-id="${d.id}" data-next="proposal">${icon("fileText",14)} Criar / avançar proposta</button>`:x.classification==="partner_fit"?`<button class="btn secondary" data-action="diagnostic-next" data-id="${d.id}" data-next="partner">${icon("handshake",14)} Agendar indicação</button>`:`<button class="btn secondary" data-action="diagnostic-next" data-id="${d.id}" data-next="followup">${icon("calendar",14)} Agendar acompanhamento</button>`}</div></div></div>`}
function renderProposalContract(d){const p=d.proposal||{},c=d.contract||{};return `<div class="journey-grid"><div class="journey-panel"><div class="section-title">Proposta comercial</div><div class="journey-fields">${inputPath("Código","proposal.code",p.code,"text","deal","PROP-AAAA-0001")}${inputPath("Versão","proposal.version",p.version,"number")}${inputPath("Valor","proposal.value",p.value,"number")}${inputPath("Enviada em","proposal.sentDate",p.sentDate,"date")}${inputPath("Validade","proposal.validUntil",p.validUntil,"date")}${selectPath("Status","proposal.status",p.status,PROPOSAL_STATUSES.map(x=>[x,{draft:"Rascunho",sent:"Enviada",viewed:"Visualizada",negotiating:"Em negociação",accepted:"Aceita",rejected:"Rejeitada",expired:"Expirada"}[x]]))}</div>${textAreaField("Forma de pagamento","proposal.paymentTerms",p.paymentTerms)}</div><div class="journey-panel"><div class="section-title">Contrato e entrada</div><div class="journey-fields">${inputPath("Código","contract.code",c.code,"text","deal","CTR-AAAA-0001")}${selectPath("Status","contract.status",c.status,CONTRACT_STATUSES.map(x=>[x,{not_started:"Não iniciado",draft:"Rascunho",sent:"Enviado",signed:"Assinado",cancelled:"Cancelado"}[x]]))}${inputPath("Enviado em","contract.sentDate",c.sentDate,"date")}${inputPath("Assinado em","contract.signedDate",c.signedDate,"date")}${inputPath("Referência assinatura","contract.signatureRef",c.signatureRef,"text","deal","Clicksign / ID")}${selectPath("Entrada","entryStatus",d.entryStatus||"pending",[["pending","Pendente"],["paid","Paga"],["waived","Não aplicável"]])}</div><div class="contract-readiness ${c.status==="signed"&&(d.entryStatus==="paid"||d.entryStatus==="waived")?"ready":""}">${c.status==="signed"&&(d.entryStatus==="paid"||d.entryStatus==="waived")?`${icon("checkSquare",16)} <strong>Pronto para converter em projeto.</strong>`:`${icon("alert",16)} Para criar o projeto: contrato assinado + entrada confirmada.`}</div></div></div>`}

function renderProjectDrawer(id){const p=project(id);if(!p)return"";const c=company(p.companyId),d=deal(p.dealId),a=latestActivityForProject(p.id),acts=data.activities.filter(x=>x.projectId===p.id).sort((a,b)=>activitySortKey(a).localeCompare(activitySortKey(b))),history=data.history.filter(x=>x.entityType==="project"&&x.entityId===p.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),notes=data.notes.filter(x=>x.entityType==="project"&&x.entityId===p.id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt)),progress=p.deliverables?.length?Math.round(p.deliverables.filter(x=>x.done).length/p.deliverables.length*100):0,received=(p.financial?.installments||[]).filter(x=>x.status==="paid").reduce((s,x)=>s+Number(x.value||0),0),receivable=(p.financial?.installments||[]).filter(x=>x.status!=="paid").reduce((s,x)=>s+Number(x.value||0),0);return `<div class="drawer-overlay" data-action="close-project"><aside class="drawer project-drawer"><div class="drawer-top"><span class="drawer-code">${h(p.code)}</span><span class="chip dot" style="--tone:${projectStage(p.stage).color}">${h(projectStage(p.stage).label)}</span><span class="toolbar-spacer"></span><button class="btn sm secondary" data-action="new-activity" data-project="${p.id}">${icon("plus",13)} Atividade</button><button class="close" data-action="close-project">${icon("x",17)}</button></div><div class="drawer-body"><main class="drawer-main"><div><div class="drawer-title">${h(p.title)}</div><div class="drawer-company">${h(c?.name||"—")} · origem ${h(d?.code||"sem oportunidade")}</div></div><div class="project-hero"><div><small>Progresso dos entregáveis</small><strong>${progress}%</strong><div class="project-progress large"><span style="width:${progress}%"></span></div></div><div><small>Prazo-alvo</small><strong class="${p.targetDate&&p.targetDate<todayStr()&&p.stage!=="done"?"due overdue":""}">${fmtDate(p.targetDate)}</strong></div><div><small>Valor</small><strong>${money(p.value)}</strong></div></div><section class="section"><div class="section-title">Próxima ação</div>${a?`<button class="note clickable-note" data-action="open-activity" data-id="${a.id}"><div class="note-head"><strong>${icon(activityType(a.type).icon,14)} ${h(a.subject)}</strong><span>${fmtDate(a.dueDate)} ${h(a.dueTime)}</span></div></button>`:`<div class="empty"><strong>Nenhuma próxima ação</strong>O projeto aparecerá no painel de atenção.<div style="margin-top:8px"><button class="btn sm secondary" data-action="new-activity" data-project="${p.id}">${icon("plus",13)} Agendar</button></div></div>`}</section><section class="section"><div class="tabs">${[["overview","Visão geral"],["scope","Escopo"],["finance",`Financeiro · ${money(receivable)} a receber`],["documents","Documentos"],["changes",`Change Requests · ${(p.changeRequests||[]).length}`],["activities",`Atividades · ${acts.length}`],["history","Histórico"],["notes","Notas"]].map(([v,l])=>`<button class="tab ${ui.projectTab===v?"active":""}" data-action="project-tab" data-value="${v}">${l}</button>`).join("")}</div><div>${renderProjectTab(p,acts,history,notes)}</div></section></main><aside class="drawer-side"><div class="mini-stats"><div class="mini-stat"><small>Contratado</small><strong>${money(p.value)}</strong></div><div class="mini-stat"><small>Recebido</small><strong>${money(received)}</strong></div></div>${propertySelect("Etapa","stage",p.stage,PROJECT_STAGES.map(s=>[s.id,s.label]),"project")}${propertySelect("Responsável","ownerId",p.ownerId,data.users.map(x=>[x.id,x.name]),"project")}${propertyInput("Início","startDate",p.startDate,"date","project")}${propertyInput("Prazo-alvo","targetDate",p.targetDate,"date","project")}<div class="prop-group"><div class="section-title">Referências</div><div class="prop-row"><label>Oportunidade</label><button class="link-button" data-action="open-deal" data-id="${p.dealId}">${h(d?.code||"—")}</button></div><div class="prop-row"><label>Empresa</label><button class="link-button" data-action="open-company" data-id="${p.companyId}">${h(c?.name||"—")}</button></div><div class="prop-row"><label>Serviço</label><span>${h(service(p.serviceId)?.name||"—")}</span></div></div><div class="prop-group"><div class="section-title">Metadados</div><div class="prop-row"><label>Criado</label><span>${fmtDateTime(p.createdAt)}</span></div><div class="prop-row"><label>Atualizado</label><span>${fmtDateTime(p.updatedAt)}</span></div></div></aside></div></aside></div>`}
function renderProjectTab(p,acts,history,notes){if(ui.projectTab==="overview")return `<div class="journey-grid"><div class="journey-panel"><div class="section-title">Objetivo</div>${textAreaField("Objetivo do projeto","objective",p.objective,"project")}${textAreaField("Descrição / contexto","description",p.description,"project")}</div><div class="journey-panel"><div class="section-title">Entregáveis</div><div class="deliverable-list">${p.deliverables?.length?p.deliverables.map(x=>`<button class="deliverable ${x.done?"done":""}" data-action="toggle-deliverable" data-project="${p.id}" data-deliverable="${x.id}"><span>${x.done?"✓":"○"}</span><strong>${h(x.label)}</strong></button>`).join(""):`<div class="empty">Nenhum entregável cadastrado.</div>`}</div><button class="btn sm secondary" data-action="add-deliverable" data-id="${p.id}">${icon("plus",13)} Adicionar entregável</button></div></div>`;if(ui.projectTab==="scope")return `<div class="journey-grid"><div class="journey-panel"><div class="section-title">Escopo</div>${textAreaField("Dentro do escopo","inScope",p.inScope,"project")}${textAreaField("Fora do escopo","outOfScope",p.outOfScope,"project")}</div><div class="journey-panel"><div class="section-title">Dependências & riscos</div>${textAreaField("Dependências do cliente","dependencies",p.dependencies,"project")}${textAreaField("Riscos","risks",p.risks,"project")}</div></div>`;if(ui.projectTab==="finance")return renderProjectFinance(p);if(ui.projectTab==="documents")return renderProjectDocuments(p);if(ui.projectTab==="changes")return renderChangeRequests(p);if(ui.projectTab==="activities")return `<div class="deal-activity-list">${acts.length?acts.map(a=>calendarAgendaItem(a,true)).join(""):`<div class="empty">Nenhuma atividade vinculada.</div>`}</div>`;if(ui.projectTab==="history")return `<div class="timeline">${history.map(historyItem).join("")}</div>`;return `<div class="timeline">${notes.map(noteItem).join("")}</div><form id="note-form" class="composer" data-entity="project" data-id="${p.id}" style="margin-top:12px"><textarea class="textarea" name="note" placeholder="Adicionar nota interna…"></textarea><button class="btn primary" type="submit">Adicionar</button></form>`}
function renderProjectFinance(p){const rows=p.financial?.installments||[],contracted=Number(p.value||0),paid=rows.filter(x=>x.status==="paid").reduce((s,x)=>s+Number(x.value||0),0),pending=rows.filter(x=>x.status!=="paid").reduce((s,x)=>s+Number(x.value||0),0);return `<div><div class="finance-summary"><div><small>Contratado</small><strong>${money(contracted)}</strong></div><div><small>Recebido</small><strong>${money(paid)}</strong></div><div><small>A receber</small><strong>${money(pending)}</strong></div></div><div class="table-wrap finance-table"><table><thead><tr><th>Parcela</th><th>Valor</th><th>Vencimento</th><th>Status</th><th>Documento</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="cell-title">${h(x.label)}</td><td class="money">${money(x.value)}</td><td>${fmtDate(x.dueDate)}</td><td><select class="select compact" data-installment-status="${x.id}" data-project="${p.id}"><option value="pending" ${x.status==="pending"?"selected":""}>Pendente</option><option value="invoiced" ${x.status==="invoiced"?"selected":""}>Faturada</option><option value="paid" ${x.status==="paid"?"selected":""}>Paga</option></select></td><td>${h(x.invoice||"—")}</td></tr>`).join("")}</tbody></table></div><div style="margin-top:10px"><button class="btn sm secondary" data-action="add-installment" data-id="${p.id}">${icon("plus",13)} Adicionar parcela</button></div></div>`}
function renderProjectDocuments(p){const phases=[...new Set(DOCUMENT_DEFS.map(x=>x.phase))];return `<div class="project-docs">${phases.map(phase=>`<div class="doc-phase"><div class="section-title">${h(phase)}</div>${DOCUMENT_DEFS.filter(x=>x.phase===phase).map(def=>{const doc=p.documents?.[def.id]||{status:"pending"};return `<div class="doc-record ${doc.status}"><div><strong>${h(def.label)}</strong><small>${doc.code?h(doc.code):DOC_STATUS_LABELS[doc.status]||doc.status}</small></div><select class="select compact" data-doc-status="${def.id}" data-project="${p.id}">${DOC_STATUSES.map(s=>`<option value="${s}" ${doc.status===s?"selected":""}>${h(DOC_STATUS_LABELS[s])}</option>`).join("")}</select></div>`}).join("")}</div>`).join("")}</div>`}
function renderChangeRequests(p){return `<div class="cr-list">${(p.changeRequests||[]).length?p.changeRequests.map(cr=>`<article class="cr-card"><div class="cr-top"><div><span class="deal-code">${h(cr.code)}</span><strong>${h(cr.title)}</strong></div><span class="chip dot" style="--tone:${cr.status==="approved"?"#059669":cr.status==="rejected"?"#EA2A0E":"#D97706"}">${h({pending:"Pendente",approved:"Aprovada",rejected:"Rejeitada",implemented:"Implementada"}[cr.status]||cr.status)}</span></div><p>${h(cr.description||"")}</p><div class="cr-impact"><span>Valor <strong>${money(cr.amount)}</strong></span><span>Prazo <strong>${cr.daysImpact>0?`+${cr.daysImpact} dias`:"sem impacto"}</strong></span></div><select class="select compact" data-cr-status="${cr.id}" data-project="${p.id}"><option value="pending" ${cr.status==="pending"?"selected":""}>Pendente</option><option value="approved" ${cr.status==="approved"?"selected":""}>Aprovada</option><option value="rejected" ${cr.status==="rejected"?"selected":""}>Rejeitada</option><option value="implemented" ${cr.status==="implemented"?"selected":""}>Implementada</option></select></article>`).join(""):`<div class="empty"><strong>Nenhuma mudança formalizada</strong>Solicitações fora do escopo devem virar Change Request.</div>`}<button class="btn sm secondary" data-action="new-cr" data-id="${p.id}">${icon("gitPull",13)} Nova Change Request</button></div>`}

function historyItem(x){const u=user(x.actorId),d=x.entityType==="deal"?deal(x.entityId):null,p=x.entityType==="project"?project(x.entityId):null;return `<div class="timeline-item"><span class="timeline-time">${fmtDateTime(x.createdAt)}</span><span class="timeline-dot"></span><span class="timeline-text"><strong>${h(u?.name||"Sistema")}</strong> ${h(x.text)}${d&&ui.view==="dashboard"?` <button class="btn sm ghost" data-action="open-deal" data-id="${d.id}">${h(d.code)}</button>`:""}${p&&ui.view==="dashboard"?` <button class="btn sm ghost" data-action="open-project" data-id="${p.id}">${h(p.code)}</button>`:""}</span></div>`}
function noteItem(n){const u=user(n.authorId);return `<div class="note"><div class="note-head"><strong>${h(u?.name||"Usuário")}</strong><span>${fmtDateTime(n.createdAt)}</span></div><div>${h(n.body)}</div></div>`}
function companyDetailModal(id){const c=company(id);if(!c)return"";const contacts=data.contacts.filter(x=>x.companyId===id),deals=data.deals.filter(x=>x.companyId===id),projects=data.projects.filter(x=>x.companyId===id),won=deals.filter(d=>d.stage==="won").reduce((s,d)=>s+Number(d.amount||0),0);return modalShell(c.name,`${c.code} · ICP ${icpScore(c)}/100`,`<div class="grid-2"><div class="journey-panel"><div class="section-title">Perfil do escritório</div><div class="company-detail-grid"><label>Carteira<input class="input" type="number" data-company-field="clientCount" data-company="${c.id}" value="${c.clientCount||0}"></label><label>Equipe<input class="input" type="number" data-company-field="teamSize" data-company="${c.id}" value="${c.teamSize||0}"></label><label>ERP<input class="input" data-company-field="erp" data-company="${c.id}" value="${h(c.erp||"")}"></label><label>Maturidade digital<select class="select" data-company-field="digitalMaturity" data-company="${c.id}">${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(c.digitalMaturity)===n?"selected":""}>${n}/5</option>`).join("")}</select></label><label class="full">Outros sistemas<input class="input" data-company-field="otherSystems" data-company="${c.id}" value="${h(c.otherSystems||"")}"></label><label class="full">Regimes atendidos<input class="input" data-company-field="regimes" data-company="${c.id}" value="${h(c.regimes||"")}"></label></div></div><div class="journey-panel"><div class="section-title">Relacionamento</div><p><strong>Cidade:</strong> ${h(c.city||"—")}</p><p><strong>Site:</strong> ${h(c.site||"—")}</p><p><strong>Contatos:</strong> ${contacts.length}</p><p><strong>Oportunidades abertas:</strong> ${deals.filter(d=>!isClosed(d)).length}</p><p><strong>Projetos ativos:</strong> ${projects.filter(p=>p.stage!=="done").length}</p><p><strong>Receita ganha:</strong> ${money(won)}</p></div></div><div class="section" style="margin-top:16px"><div class="section-title">Contatos</div>${contacts.map(ct=>`<div class="note"><strong>${h(ct.name)}</strong> · ${h(ct.role||"—")} · ${h(DECISION_ROLES.find(x=>x[0]===ct.decisionRole)?.[1]||"")}<div class="muted">${h(ct.preferredChannel||"")} · ${h(ct.email||"")} · ${h(ct.phone||"")}</div></div>`).join("")||`<div class="muted">Nenhum contato.</div>`}</div><div class="section" style="margin-top:16px"><div class="section-title">Oportunidades</div>${deals.map(d=>`<button class="btn secondary" data-action="open-deal-from-modal" data-id="${d.id}">${h(d.code)} · ${h(d.title)} · ${money(d.amount)}</button>`).join(" ")||`<div class="muted">Nenhuma oportunidade.</div>`}</div><div class="section" style="margin-top:16px"><div class="section-title">Projetos</div>${projects.map(p=>`<button class="btn secondary" data-action="open-project-from-modal" data-id="${p.id}">${h(p.code)} · ${h(p.title)}</button>`).join(" ")||`<div class="muted">Nenhum projeto.</div>`}</div>`)}
function contactDetailModal(id){const ct=contact(id);if(!ct)return"";const ds=data.deals.filter(d=>d.primaryContactId===id);return modalShell(ct.name,`${ct.code} · ${company(ct.companyId)?.name||""}`,`<div class="grid-2"><div><p><strong>Cargo:</strong> ${h(ct.role||"—")}</p><p><strong>E-mail:</strong> ${h(ct.email||"—")}</p><p><strong>Telefone:</strong> ${h(ct.phone||"—")}</p></div><div><p><strong>Papel:</strong> ${h(DECISION_ROLES.find(x=>x[0]===ct.decisionRole)?.[1]||"—")}</p><p><strong>Canal preferido:</strong> ${h(ct.preferredChannel||"—")}</p><p><strong>Contato comercial:</strong> ${ct.commercialOptIn?"Permitido":"Não marcado"}</p></div></div><div class="section" style="margin-top:16px"><div class="section-title">Oportunidades relacionadas</div>${ds.map(d=>`<button class="btn secondary" data-action="open-deal-from-modal" data-id="${d.id}">${h(d.code)} · ${h(d.title)}</button>`).join(" ")||`<div class="muted">Nenhuma oportunidade.</div>`}</div>`)}

function renderModal(){switch(ui.modal.type){case"deal":return dealModal();case"company":return companyModal();case"contact":return contactModal();case"partner":return partnerModal();case"activity":return activityModal();case"activityDetail":return activityDetailModal(ui.modal.id);case"companyDetail":return companyDetailModal(ui.modal.id);case"contactDetail":return contactDetailModal(ui.modal.id);case"deliverable":return deliverableModal(ui.modal.projectId);case"installment":return installmentModal(ui.modal.projectId);case"cr":return changeRequestModal(ui.modal.projectId);default:return""}}
function modalShell(title,sub,body,footer=""){return `<div class="overlay" data-action="close-modal"><div class="modal"><div class="modal-head"><div><div class="modal-title">${h(title)}</div><div class="modal-sub">${h(sub||"")}</div></div><button class="close" data-action="close-modal">${icon("x",17)}</button></div><div class="modal-body">${body}</div><div class="modal-foot">${footer||`<button class="btn secondary" data-action="close-modal">Fechar</button>`}</div></div></div>`}
