function activityModal(){const activityId=ui.modal.activityId||"",existing=activity(activityId),dealId=ui.modal.dealId||existing?.dealId||"",projectId=ui.modal.projectId||existing?.projectId||"",d=deal(dealId),p=project(projectId),defaults=ui.modal.defaults||{},chosenCompany=existing?.companyId||d?.companyId||p?.companyId||defaults.companyId||"",chosenContact=existing?.contactId||d?.primaryContactId||defaults.contactId||"",date=existing?.dueDate||ui.modal.date||defaults.dueDate||todayStr(),start=existing?.dueTime||defaults.dueTime||"10:00",end=existing?.endTime||defaults.endTime||"11:00";return modalShell(activityId?"Editar atividade":"Nova atividade",activityId?"Atualize o próximo passo.":"Agende um compromisso comercial ou operacional.",`<form id="activity-form" class="form-grid"><input type="hidden" name="activityId" value="${h(activityId)}"><div class="field full"><label>Assunto <span class="req">*</span></label><input class="input" name="subject" required value="${h(existing?.subject||defaults.subject||"")}"></div><div class="field"><label>Tipo</label><select class="select" name="type">${ACTIVITY_TYPES.map(t=>`<option value="${t.id}" ${(existing?.type||defaults.type||"task")===t.id?"selected":""}>${h(t.label)}</option>`).join("")}</select></div><div class="field"><label>Prioridade</label><select class="select" name="priority">${PRIORITIES.map(x=>`<option value="${x}" ${(existing?.priority||"normal")===x?"selected":""}>${h(x.charAt(0).toUpperCase()+x.slice(1))}</option>`).join("")}</select></div><div class="field"><label>Responsável</label><select class="select" name="ownerId">${data.users.map(u=>`<option value="${u.id}" ${u.id===(existing?.ownerId||d?.ownerId||p?.ownerId||defaults.ownerId||currentUser().id)?"selected":""}>${h(u.name)}</option>`).join("")}</select></div><div class="field"><label>Data</label><input class="input" type="date" name="dueDate" value="${h(date)}"></div><div class="field"><label>Início</label><input class="input" type="time" name="dueTime" value="${h(start)}"></div><div class="field"><label>Fim</label><input class="input" type="time" name="endTime" value="${h(end)}"></div><div class="field full"><label>Oportunidade</label><select class="select" name="dealId" data-activity-context="deal"><option value="">Sem oportunidade</option>${data.deals.map(x=>`<option value="${x.id}" ${x.id===dealId?"selected":""}>${h(x.code)} · ${h(x.title)}</option>`).join("")}</select></div><div class="field full"><label>Projeto</label><select class="select" name="projectId" data-activity-context="project"><option value="">Sem projeto</option>${data.projects.map(x=>`<option value="${x.id}" ${x.id===projectId?"selected":""}>${h(x.code)} · ${h(x.title)}</option>`).join("")}</select></div><div class="field"><label>Empresa</label><select class="select" name="companyId" data-contact-filter-target="contactId"><option value="">Sem empresa</option>${data.companies.map(c=>`<option value="${c.id}" ${c.id===chosenCompany?"selected":""}>${h(c.name)}</option>`).join("")}</select></div><div class="field"><label>Contato</label><select class="select" name="contactId" data-empty-label="Sem contato" ${!chosenCompany||contactsForCompany(chosenCompany).length===0?"disabled":""}>${contactOptionsForCompany(chosenCompany,chosenContact,"Sem contato")}</select></div><div class="field full"><label>Descrição</label><textarea class="textarea" name="description">${h(existing?.description||"")}</textarea></div></form>`,`<button class="btn secondary" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit" form="activity-form">${activityId?"Salvar":"Agendar"}</button>`)}
function activityDetailModal(id){const a=activity(id);if(!a)return"";const {type,u,c,d,p}=activityContext(a);return modalShell(a.subject,`${type.label} · ${activityStatus(a)==="done"?"Concluída":fmtDate(a.dueDate)}`,`<div class="activity-detail"><div class="activity-detail-hero" style="--activity-color:${type.color}"><span class="activity-detail-icon">${icon(type.icon,20)}</span><div><strong>${h(type.label)}</strong><span>${fmtDate(a.dueDate)} · ${h(a.dueTime||"—")}${a.endTime?`–${h(a.endTime)}`:""}</span></div></div><div class="grid-2 activity-detail-grid"><div><div class="section-title">Responsável</div><p>${avatar(u)} ${h(u?.name||"—")}</p></div><div><div class="section-title">Contexto</div><p>${h(c?.name||"Atividade interna")}${d?` · ${h(d.code)}`:""}${p?` · ${h(p.code)}`:""}</p></div></div>${a.description?`<div class="section"><div class="section-title">Descrição</div><div class="description">${h(a.description)}</div></div>`:""}</div>`,`<button class="btn secondary ghost-danger" data-action="delete-activity" data-id="${a.id}">Excluir</button><span class="toolbar-spacer"></span><button class="btn secondary" data-action="edit-activity" data-id="${a.id}">Editar</button>${a.completed?"":`<button class="btn secondary" data-action="complete-next" data-id="${a.id}">Concluir + próxima</button><button class="btn primary" data-action="complete-activity" data-id="${a.id}">Concluir</button>`}`)}
function deliverableModal(projectId){return modalShell("Novo entregável",project(projectId)?.code||"Projeto",`<form id="deliverable-form" class="form-grid"><input type="hidden" name="projectId" value="${h(projectId)}"><div class="field full"><label>Entregável <span class="req">*</span></label><input class="input" name="label" required placeholder="Ex.: Manual rápido do usuário"></div></form>`,`<button class="btn secondary" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit" form="deliverable-form">Adicionar</button>`)}
function installmentModal(projectId){const p=project(projectId);return modalShell("Nova parcela",p?.code||"Projeto",`<form id="installment-form" class="form-grid"><input type="hidden" name="projectId" value="${h(projectId)}"><div class="field"><label>Descrição <span class="req">*</span></label><input class="input" name="label" required placeholder="Ex.: Parcela intermediária"></div><div class="field"><label>Valor</label><input class="input" type="number" step="0.01" name="value" value="0"></div><div class="field"><label>Vencimento</label><input class="input" type="date" name="dueDate" value="${isoDay(7)}"></div><div class="field"><label>Status</label><select class="select" name="status"><option value="pending">Pendente</option><option value="invoiced">Faturada</option><option value="paid">Paga</option></select></div><div class="field full"><label>Documento / NFS-e</label><input class="input" name="invoice"></div></form>`,`<button class="btn secondary" data-action="close-modal">Cancelar</button><button class="btn primary" type="submit" form="installment-form">Adicionar</button>`)}
