function setPath(obj,path,value){const parts=path.split(".");let cur=obj;for(let i=0;i<parts.length-1;i++){cur[parts[i]]=cur[parts[i]]||{};cur=cur[parts[i]]}const key=parts.at(-1);const numeric=["duration","monthlyHours","version","value"].includes(key);cur[key]=numeric?Number(value||0):value}
function updateDealField(id,field,value){const d=deal(id);if(!d)return;const before=d[field];let v=value;if(["amount","probability"].includes(field))v=Number(value||0);d[field]=v;if(field==="stage"){d.probability=stage(v).probability;d.closedAt=["won","lost"].includes(v)?new Date().toISOString():null}if(field==="companyId"&&!data.contacts.some(c=>c.id===d.primaryContactId&&c.companyId===v))d.primaryContactId="";d.updatedAt=new Date().toISOString();addHistory("deal",id,`alterou ${field}: ${before||"—"} → ${v||"—"}.`);saveData();render()}
function updateDealPath(id,path,value){const d=deal(id);if(!d)return;setPath(d,path,value);if(path==="proposal.value"&&Number(value)>0)d.amount=Number(value);if(path==="diagnostic.classification"&&value==="elevar_fit"&&d.stage==="diagnosis")d.probability=stage(d.stage).probability;d.updatedAt=new Date().toISOString();addHistory("deal",id,`atualizou ${path}.`);saveData();render()}
function updateProjectField(id,field,value){const p=project(id);if(!p)return;p[field]=["value"].includes(field)?Number(value||0):value;if(field==="stage"){p.status=value==="done"?"closed":"active";p.closedAt=value==="done"?new Date().toISOString():null}p.updatedAt=new Date().toISOString();addHistory("project",id,`alterou ${field}.`);saveData();render()}
function updateProjectPath(id,path,value){const p=project(id);if(!p)return;setPath(p,path,value);p.updatedAt=new Date().toISOString();addHistory("project",id,`atualizou ${path}.`);saveData();render()}
function moveDeal(id,newStage){const d=deal(id);if(!d||d.stage===newStage)return;const old=stage(d.stage).label;d.stage=newStage;d.probability=stage(newStage).probability;d.updatedAt=new Date().toISOString();d.closedAt=["won","lost"].includes(newStage)?new Date().toISOString():null;addHistory("deal",id,`moveu a oportunidade de ${old} para ${stage(newStage).label}.`,"stage");saveData();toast(`${d.code} movida para ${stage(newStage).label}.`);render()}
function moveProject(id,newStage){const p=project(id);if(!p||p.stage===newStage)return;const old=projectStage(p.stage).label;p.stage=newStage;p.status=newStage==="done"?"closed":"active";p.updatedAt=new Date().toISOString();p.closedAt=newStage==="done"?new Date().toISOString():null;addHistory("project",id,`moveu o projeto de ${old} para ${projectStage(newStage).label}.`,"stage");saveData();toast(`${p.code} movido para ${projectStage(newStage).label}.`);render()}
function convertDealToProject(id){const d=deal(id);if(!d||d.convertedProjectId)return;const ready=d.stage==="won"||(d.stage==="contract"&&d.contract?.status==="signed"&&["paid","waived"].includes(d.entryStatus));if(!ready){toast("Para converter: contrato assinado e entrada confirmada, ou oportunidade já ganha.","error");return}if(d.stage!=="won"){d.stage="won";d.probability=100;d.closedAt=new Date().toISOString()}const docs=defaultDocuments();if(d.diagnostic?.summary)docs.diagnostic.status="approved";if(d.diagnostic?.date)docs.discovery.status="approved";if(d.proposal?.status==="accepted"){docs.proposal.status="approved";docs.proposal.code=d.proposal.code||""}if(d.contract?.status==="signed"){docs.contract.status="approved";docs.contract.code=d.contract.code||"";docs.signature.status="approved"}const code=nextCode("project"),pid=uid("p"),value=Number(d.proposal?.value||d.amount||0),entryPaid=d.entryStatus==="paid",p={id:pid,code,dealId:d.id,companyId:d.companyId,title:d.title,serviceId:d.serviceId,ownerId:d.ownerId,stage:"awaiting_kickoff",status:"active",startDate:todayStr(),targetDate:isoDay(30),value,description:d.description||"",objective:d.diagnostic?.recommendation||"",inScope:"",outOfScope:"",dependencies:"",risks:"",deliverables:[],documents:docs,financial:{installments:[{id:uid("fin"),label:"Entrada 50%",value:value/2,dueDate:todayStr(),status:entryPaid?"paid":"pending",invoice:"",paidDate:entryPaid?todayStr():""},{id:uid("fin"),label:"Aceite 50%",value:value/2,dueDate:isoDay(30),status:"pending",invoice:"",paidDate:""}]},changeRequests:[],createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),closedAt:null};data.projects.push(p);d.convertedProjectId=pid;d.updatedAt=new Date().toISOString();addHistory("deal",d.id,`converteu a oportunidade em ${code}.`,"conversion");addHistory("project",p.id,`projeto criado a partir de ${d.code}.`,"created");saveData();ui.dealDrawerId=null;ui.projectDrawerId=pid;ui.projectTab="overview";toast(`${code} criado com sucesso.`);render()}
function openDeal(id){ui.dealDrawerId=id;ui.projectDrawerId=null;ui.drawerTab="summary";ui.modal=null;ui.search="";render()}
function openProject(id){ui.projectDrawerId=id;ui.dealDrawerId=null;ui.projectTab="overview";ui.modal=null;ui.search="";render()}
function completeActivity(id,{silent=false}={}){const a=activity(id);if(!a||a.completed)return;a.completed=true;a.completedAt=new Date().toISOString();if(a.dealId)addHistory("deal",a.dealId,`concluiu a atividade “${a.subject}”.`,"activity");if(a.projectId)addHistory("project",a.projectId,`concluiu a atividade “${a.subject}”.`,"activity");saveData();if(!silent)toast("Atividade concluída.")}

function render(){document.getElementById("app").innerHTML=shell();bindDragDrop();renderSearchResults();renderToast()}
function renderToast(){const el=document.getElementById("toast-wrap");if(!el)return;el.innerHTML=ui.toast?`<div class="toast ${ui.toast.tone==="error"?"error":""}">${h(ui.toast.message)}</div>`:""}
function renderSearchResults(){const host=document.getElementById("search-results");if(!host)return;const q=ui.search.trim().toLowerCase();if(!q){host.innerHTML="";return}const results=[];data.companies.filter(c=>`${c.name} ${c.code}`.toLowerCase().includes(q)).slice(0,3).forEach(c=>results.push({kind:"Empresa",title:c.name,meta:c.code,action:"open-company",id:c.id}));data.contacts.filter(c=>`${c.name} ${c.email} ${company(c.companyId)?.name||""}`.toLowerCase().includes(q)).slice(0,3).forEach(c=>results.push({kind:"Contato",title:c.name,meta:company(c.companyId)?.name||c.email,action:"open-contact",id:c.id}));data.deals.filter(d=>`${d.title} ${d.code} ${company(d.companyId)?.name||""}`.toLowerCase().includes(q)).slice(0,4).forEach(d=>results.push({kind:"Oportunidade",title:d.title,meta:`${d.code} · ${company(d.companyId)?.name||""}`,action:"open-deal",id:d.id}));data.projects.filter(p=>`${p.title} ${p.code} ${company(p.companyId)?.name||""}`.toLowerCase().includes(q)).slice(0,4).forEach(p=>results.push({kind:"Projeto",title:p.title,meta:`${p.code} · ${company(p.companyId)?.name||""}`,action:"open-project",id:p.id}));host.innerHTML=`<div class="search-results">${results.length?results.slice(0,12).map(r=>`<button class="search-result" data-action="${r.action}" data-id="${r.id}"><span class="search-kind">${r.kind}</span><span><span class="search-title">${h(r.title)}</span><span class="search-meta">${h(r.meta)}</span></span><span>${icon("chevronRight",15)}</span></button>`).join(""):`<div class="empty">Nenhum resultado.</div>`}</div>`}
function bindDragDrop(){document.querySelectorAll("[data-deal-drag]").forEach(card=>{card.addEventListener("dragstart",e=>{e.dataTransfer.setData("text/deal",card.dataset.dealDrag);card.classList.add("dragging")});card.addEventListener("dragend",()=>card.classList.remove("dragging"))});document.querySelectorAll("[data-stage-drop]").forEach(col=>{col.addEventListener("dragover",e=>{e.preventDefault();col.classList.add("drag-over")});col.addEventListener("dragleave",()=>col.classList.remove("drag-over"));col.addEventListener("drop",e=>{e.preventDefault();col.classList.remove("drag-over");const id=e.dataTransfer.getData("text/deal");if(id)moveDeal(id,col.dataset.stageDrop)})});document.querySelectorAll("[data-project-drag]").forEach(card=>{card.addEventListener("dragstart",e=>{e.dataTransfer.setData("text/project",card.dataset.projectDrag);card.classList.add("dragging")});card.addEventListener("dragend",()=>card.classList.remove("dragging"))});document.querySelectorAll("[data-project-stage-drop]").forEach(col=>{col.addEventListener("dragover",e=>{e.preventDefault();col.classList.add("drag-over")});col.addEventListener("dragleave",()=>col.classList.remove("drag-over"));col.addEventListener("drop",e=>{e.preventDefault();col.classList.remove("drag-over");const id=e.dataTransfer.getData("text/project");if(id)moveProject(id,col.dataset.projectStageDrop)})})}
function handleClick(e){const el=e.target.closest("[data-action]");if(!el)return;const action=el.dataset.action;if(["close-modal","close-drawer","close-project"].includes(action)&&(el.classList.contains("overlay")||el.classList.contains("drawer-overlay"))&&e.target!==el)return;
  if(action==="nav"){ui.view=el.dataset.view;ui.dealDrawerId=null;ui.projectDrawerId=null;ui.modal=null;render()}
  else if(action==="nav-project-stage"){ui.view="projects";ui.filters.projectStage=el.dataset.stage||"";render()}
  else if(action==="toggle-sidebar"){ui.sidebarCollapsed=!ui.sidebarCollapsed;localStorage.setItem("crm-sidebar",ui.sidebarCollapsed?"1":"0");render()}
  else if(action==="new-deal"){ui.modal={type:"deal"};render()}
  else if(action==="new-company"){ui.modal={type:"company"};render()}
  else if(action==="new-contact"){ui.modal={type:"contact"};render()}
  else if(action==="new-partner"){ui.modal={type:"partner"};render()}
  else if(action==="new-activity"){ui.modal={type:"activity",dealId:el.dataset.deal||"",projectId:el.dataset.project||"",date:el.dataset.date||"",ownerId:el.dataset.owner||""};render()}
  else if(action==="open-activity"){ui.modal={type:"activityDetail",id:el.dataset.id};render()}
  else if(action==="edit-activity"){ui.modal={type:"activity",activityId:el.dataset.id};render()}
  else if(action==="delete-activity"){const a=activity(el.dataset.id);if(a&&confirm(`Excluir a atividade “${a.subject}”?`)){data.activities=data.activities.filter(x=>x.id!==a.id);if(a.dealId)addHistory("deal",a.dealId,`excluiu a atividade “${a.subject}”.`,"activity");if(a.projectId)addHistory("project",a.projectId,`excluiu a atividade “${a.subject}”.`,"activity");saveData();ui.modal=null;toast("Atividade excluída.");render()}}
  else if(action==="complete-next"){const a=activity(el.dataset.id);if(a){completeActivity(a.id,{silent:true});ui.modal={type:"activity",dealId:a.dealId||"",projectId:a.projectId||"",defaults:{type:"followup",ownerId:a.ownerId,companyId:a.companyId,contactId:a.contactId,dueDate:addDaysKey(todayStr(),1),dueTime:a.dueTime||"10:00",endTime:a.endTime||"11:00",subject:"Próxima ação"}};toast("Atividade concluída. Agende a próxima ação.");render()}}
  else if(action==="calendar-view"){ui.calendarView=el.dataset.value;render()}
  else if(action==="calendar-prev"){const a=ui.calendarAnchor||todayStr();ui.calendarAnchor=ui.calendarView==="month"?dateKey(new Date(parseDay(a).getFullYear(),parseDay(a).getMonth()-1,1,12)):addDaysKey(a,ui.calendarView==="day"?-1:-7);render()}
  else if(action==="calendar-next"){const a=ui.calendarAnchor||todayStr();ui.calendarAnchor=ui.calendarView==="month"?dateKey(new Date(parseDay(a).getFullYear(),parseDay(a).getMonth()+1,1,12)):addDaysKey(a,ui.calendarView==="day"?1:7);render()}
  else if(action==="calendar-today"){ui.calendarAnchor=todayStr();render()}
  else if(action==="calendar-focus-day"){ui.calendarAnchor=el.dataset.date;ui.calendarView="day";render()}
  else if(action==="open-deal"){openDeal(el.dataset.id)}
  else if(action==="open-project"){openProject(el.dataset.id)}
  else if(action==="open-company"){ui.modal={type:"companyDetail",id:el.dataset.id};ui.search="";render()}
  else if(action==="open-contact"){ui.modal={type:"contactDetail",id:el.dataset.id};ui.search="";render()}
  else if(action==="open-deal-from-modal"){ui.modal=null;openDeal(el.dataset.id)}
  else if(action==="open-project-from-modal"){ui.modal=null;openProject(el.dataset.id)}
  else if(action==="close-modal"){ui.modal=null;render()}
  else if(action==="close-drawer"){ui.dealDrawerId=null;render()}
  else if(action==="close-project"){ui.projectDrawerId=null;render()}
  else if(action==="drawer-tab"){ui.drawerTab=el.dataset.value;render()}
  else if(action==="project-tab"){ui.projectTab=el.dataset.value;render()}
  else if(action==="activity-tab"){ui.filters.activity=el.dataset.value;render()}
  else if(action==="set-stage"){moveDeal(el.dataset.id,el.dataset.stage)}
  else if(action==="convert-project"){convertDealToProject(el.dataset.id)}
  else if(action==="diagnostic-next"){const d=deal(el.dataset.id),next=el.dataset.next;if(!d)return;if(next==="proposal"){if(!d.proposal.code)d.proposal.code=nextCode("proposal");d.proposal.value=Number(d.amount||0);d.proposal.status="draft";moveDeal(d.id,"proposal");ui.drawerTab="proposal"}else{ui.modal={type:"activity",dealId:d.id,defaults:{type:"followup",subject:next==="partner"?"Fazer indicação de parceiro":"Acompanhar orientação / relacionamento",dueDate:isoDay(next==="partner"?2:30)}};render()}}
  else if(action==="complete-activity"){completeActivity(el.dataset.id);ui.modal=null;render()}
  else if(action==="toggle-deliverable"){const p=project(el.dataset.project),x=p?.deliverables?.find(y=>y.id===el.dataset.deliverable);if(x){x.done=!x.done;p.updatedAt=new Date().toISOString();addHistory("project",p.id,`${x.done?"concluiu":"reabriu"} o entregável “${x.label}”.`,"deliverable");saveData();render()}}
  else if(action==="add-deliverable"){ui.modal={type:"deliverable",projectId:el.dataset.id};render()}
  else if(action==="add-installment"){ui.modal={type:"installment",projectId:el.dataset.id};render()}
  else if(action==="new-cr"){ui.modal={type:"cr",projectId:el.dataset.id};render()}
  else if(action==="save-org"){data.settings.organization=document.getElementById("org-name").value.trim()||data.settings.organization;saveData();toast("Organização atualizada.")}
  else if(action==="export-json"){exportJson()}
  else if(action==="import-json"){document.getElementById("json-import")?.click()}
  else if(action==="reset-data"){if(confirm("Restaurar a base vazia? Todos os dados operacionais cadastrados neste navegador serão apagados."))resetData()}
}
function handleChange(e){const el=e.target;
  if(el.matches("[data-filter]")){ui.filters[el.dataset.filter]=el.value;render()}
  else if(el.matches("[data-agenda-scope]")){ui.activityScope=el.value;render()}
  else if(el.matches("[data-contact-filter-target]")){const form=el.closest("form"),contactSelect=form?.querySelector(`[name="${el.dataset.contactFilterTarget}"]`);syncContactSelect(el,contactSelect)}
  else if(el.matches("[data-activity-context]")){syncActivityContext(el.closest("form"),el.dataset.activityContext,el.value)}
  else if(el.matches("[data-deal-field]")){updateDealField(ui.dealDrawerId,el.dataset.dealField,el.value)}
  else if(el.matches("[data-deal-path]")){updateDealPath(ui.dealDrawerId,el.dataset.dealPath,el.value)}
  else if(el.matches("[data-project-field]")){updateProjectField(ui.projectDrawerId,el.dataset.projectField,el.value)}
  else if(el.matches("[data-project-path]")){updateProjectPath(ui.projectDrawerId,el.dataset.projectPath,el.value)}
  else if(el.matches("[data-company-field]")){const c=company(el.dataset.company);if(c){const f=el.dataset.companyField;c[f]=["clientCount","teamSize","digitalMaturity"].includes(f)?Number(el.value||0):el.value;saveData();render()}}
  else if(el.matches("[data-installment-status]")){const p=project(el.dataset.project),x=p?.financial?.installments?.find(y=>y.id===el.dataset.installmentStatus);if(x){x.status=el.value;if(el.value==="paid")x.paidDate=todayStr();p.updatedAt=new Date().toISOString();addHistory("project",p.id,`atualizou ${x.label} para ${el.value}.`,"finance");saveData();render()}}
  else if(el.matches("[data-doc-status]")){const p=project(el.dataset.project),doc=p?.documents?.[el.dataset.docStatus];if(doc){doc.status=el.value;if(el.value==="approved"&&!doc.date)doc.date=todayStr();p.updatedAt=new Date().toISOString();addHistory("project",p.id,`atualizou ${DOCUMENT_DEFS.find(x=>x.id===el.dataset.docStatus)?.label||el.dataset.docStatus} para ${DOC_STATUS_LABELS[el.value]}.`,"document");saveData();render()}}
  else if(el.matches("[data-cr-status]")){const p=project(el.dataset.project),cr=p?.changeRequests?.find(x=>x.id===el.dataset.crStatus);if(cr){cr.status=el.value;cr.updatedAt=new Date().toISOString();addHistory("project",p.id,`atualizou ${cr.code} para ${el.value}.`,"change");saveData();render()}}
  else if(el.id==="json-import"&&el.files?.[0])importJson(el.files[0])
}
function handleInput(e){const el=e.target;if(el.id==="global-search"){ui.search=el.value;renderSearchResults()}else if(el.matches("[data-live-filter]")){ui.filters[el.dataset.liveFilter]=el.value;const pos=el.selectionStart;render();requestAnimationFrame(()=>{const n=document.querySelector(`[data-live-filter="${el.dataset.liveFilter}"]`);n?.focus();n?.setSelectionRange(pos,pos)})}}
function handleSubmit(e){
  if(e.target.id==="deal-form"){e.preventDefault();const f=new FormData(e.target),st=f.get("stage")||"lead",companyId=f.get("companyId");if(!companyId||!f.get("title")||!f.get("serviceId")){toast("Preencha empresa, oportunidade e serviço.","error");return}const ownerId=f.get("ownerId")||currentUser().id,requestedContactId=f.get("primaryContactId")||"",primaryContactId=contact(requestedContactId)?.companyId===companyId?requestedContactId:"",newDeal={id:uid("d"),code:nextCode("deal"),companyId,primaryContactId,title:f.get("title").trim(),serviceId:f.get("serviceId"),source:f.get("source")||"Outro",amount:Number(f.get("amount")||0),probability:stage(st).probability,stage:st,priority:"normal",ownerId,teamId:user(ownerId)?.teamId||"",expectedCloseDate:f.get("expectedCloseDate")||isoDay(14),description:f.get("description")||"",tags:[],diagnostic:{date:"",participants:"",duration:45,mainPain:"",currentProcess:"",tools:"",frequency:"Mensal",monthlyHours:0,impact:"Médio",summary:"",recommendation:"",classification:"unclassified",partnerReferral:"",nextStep:""},proposal:{code:"",version:1,value:Number(f.get("amount")||0),sentDate:"",validUntil:"",status:"draft",paymentTerms:"50% na contratação e 50% no aceite"},contract:{code:"",status:"not_started",sentDate:"",signedDate:"",signatureRef:""},entryStatus:"pending",convertedProjectId:"",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),closedAt:null,lostReason:""};data.deals.push(newDeal);addHistory("deal",newDeal.id,`criou ${newDeal.code}.`,"created");saveData();ui.modal=null;toast(`${newDeal.code} criada.`);openDeal(newDeal.id)}
  else if(e.target.id==="company-form"){e.preventDefault();const f=new FormData(e.target);if(!f.get("name")){toast("Informe o nome da empresa.","error");return}const c={id:uid("co"),code:nextCode("company"),name:f.get("name").trim(),segment:f.get("segment")||"",city:f.get("city")||"",site:f.get("site")||"",ownerId:f.get("ownerId")||currentUser().id,clientCount:Number(f.get("clientCount")||0),teamSize:Number(f.get("teamSize")||0),erp:f.get("erp")||"",otherSystems:f.get("otherSystems")||"",regimes:f.get("regimes")||"",digitalMaturity:Number(f.get("digitalMaturity")||2),createdAt:new Date().toISOString()};data.companies.push(c);saveData();ui.modal=null;toast(`${c.name} cadastrada.`);render()}
  else if(e.target.id==="contact-form"){e.preventDefault();const f=new FormData(e.target);if(!f.get("companyId")||!f.get("name")){toast("Informe empresa e nome do contato.","error");return}const c={id:uid("ct"),code:nextCode("contact"),companyId:f.get("companyId"),name:f.get("name").trim(),role:f.get("role")||"",email:f.get("email")||"",phone:f.get("phone")||"",preferredChannel:f.get("preferredChannel")||"WhatsApp",commercialOptIn:f.get("commercialOptIn")==="on",decisionRole:f.get("decisionRole")||"decision_maker",createdAt:new Date().toISOString()};data.contacts.push(c);saveData();ui.modal=null;toast(`${c.name} cadastrado.`);render()}
  else if(e.target.id==="partner-form"){e.preventDefault();const f=new FormData(e.target);if(!f.get("name")){toast("Informe o nome do parceiro.","error");return}data.partners.push({id:uid("par"),name:f.get("name").trim(),category:f.get("category")||"",city:f.get("city")||"",contact:f.get("contact")||"",notes:f.get("notes")||"",createdAt:new Date().toISOString()});saveData();ui.modal=null;toast("Parceiro cadastrado.");render()}
  else if(e.target.id==="activity-form"){e.preventDefault();const f=new FormData(e.target);if(!f.get("subject")){toast("Informe o assunto.","error");return}const activityId=f.get("activityId")||"",dealId=f.get("dealId")||"",projectId=f.get("projectId")||"",d=deal(dealId),p=project(projectId),companyId=f.get("companyId")||d?.companyId||p?.companyId||"",requestedContactId=f.get("contactId")||d?.primaryContactId||"",contactId=contact(requestedContactId)?.companyId===companyId?requestedContactId:"";const payload={dealId,projectId,companyId,contactId,ownerId:f.get("ownerId")||currentUser().id,type:f.get("type")||"task",priority:f.get("priority")||"normal",subject:f.get("subject").trim(),dueDate:f.get("dueDate")||todayStr(),dueTime:f.get("dueTime")||"10:00",endTime:f.get("endTime")||"",description:f.get("description")||""};if(activityId){const a=activity(activityId);Object.assign(a,payload);if(dealId)addHistory("deal",dealId,`editou a atividade “${a.subject}”.`,"activity");if(projectId)addHistory("project",projectId,`editou a atividade “${a.subject}”.`,"activity");saveData();ui.modal={type:"activityDetail",id:a.id};toast("Atividade atualizada.");render()}else{const a={id:uid("a"),...payload,completed:false,outcome:"",createdAt:new Date().toISOString()};data.activities.push(a);if(dealId)addHistory("deal",dealId,`agendou a atividade “${a.subject}” para ${fmtDate(a.dueDate)}.`,"activity");if(projectId)addHistory("project",projectId,`agendou a atividade “${a.subject}” para ${fmtDate(a.dueDate)}.`,"activity");saveData();ui.modal=null;toast("Atividade agendada.");render()}}
  else if(e.target.id==="note-form"){e.preventDefault();const f=new FormData(e.target),body=f.get("note").trim();if(!body)return;const entityType=e.target.dataset.entity,entityId=e.target.dataset.id;data.notes.push({id:uid("n"),entityType,entityId,authorId:currentUser().id,body,createdAt:new Date().toISOString()});addHistory(entityType,entityId,"adicionou uma nota interna.","note");saveData();toast("Nota adicionada.");render()}
  else if(e.target.id==="deliverable-form"){e.preventDefault();const f=new FormData(e.target),p=project(f.get("projectId")),label=f.get("label").trim();if(!p||!label)return;p.deliverables.push({id:uid("del"),label,done:false});addHistory("project",p.id,`adicionou o entregável “${label}”.`,"deliverable");saveData();ui.modal=null;toast("Entregável adicionado.");render()}
  else if(e.target.id==="installment-form"){e.preventDefault();const f=new FormData(e.target),p=project(f.get("projectId"));if(!p)return;p.financial.installments.push({id:uid("fin"),label:f.get("label"),value:Number(f.get("value")||0),dueDate:f.get("dueDate")||"",status:f.get("status")||"pending",invoice:f.get("invoice")||"",paidDate:f.get("status")==="paid"?todayStr():""});addHistory("project",p.id,`adicionou a parcela “${f.get("label")}”.`,"finance");saveData();ui.modal=null;toast("Parcela adicionada.");render()}
  else if(e.target.id==="cr-form"){e.preventDefault();const f=new FormData(e.target),p=project(f.get("projectId"));if(!p)return;const code=`CR-${p.code.replace("PRJ-","")}-${String((p.changeRequests?.length||0)+1).padStart(2,"0")}`,cr={id:uid("cr"),code,title:f.get("title"),description:f.get("description")||"",amount:Number(f.get("amount")||0),daysImpact:Number(f.get("daysImpact")||0),status:"pending",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};p.changeRequests.push(cr);addHistory("project",p.id,`criou ${code}: ${cr.title}.`,"change");saveData();ui.modal=null;toast(`${code} criada.`);render()}
}
function exportJson(){const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`elevar-crm-backup-${todayStr()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Backup JSON gerado.")}
function importJson(file){const r=new FileReader();r.onload=()=>{try{const obj=JSON.parse(r.result);if(!obj.companies||!obj.contacts||!obj.deals||!obj.activities)throw new Error();data=migrateLegacy(obj);saveData();ui.modal=null;toast("Dados importados com sucesso.");render()}catch(_){toast("Arquivo JSON incompatível.","error")}};r.readAsText(file)}

document.addEventListener("click",handleClick);document.addEventListener("change",handleChange);document.addEventListener("input",handleInput);document.addEventListener("submit",handleSubmit);document.addEventListener("keydown",e=>{if(e.key==="/"&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();document.getElementById("global-search")?.focus()}if(e.key==="Escape"){if(ui.modal){ui.modal=null;render()}else if(ui.dealDrawerId){ui.dealDrawerId=null;render()}else if(ui.projectDrawerId){ui.projectDrawerId=null;render()}}});
render();
